DELETE FROM exercises WHERE id = 'ex_db_0472' AND id NOT IN (SELECT exercise_id FROM workout_set_logs) AND id NOT IN (SELECT exercise_id FROM routine_exercises);
UPDATE exercises SET gif_url = '/gifs/2135.gif', target_muscles = 'شکم', secondary_muscles = 'شانه‌ها، پایین کمر', muscles_primary = 'abs', muscles_secondary = 'deltoids,lower-back', instructions_en = '1. Start by lying face down on the floor.
2. Place your forearms on the ground, with your elbows directly under your shoulders.
3. Extend your legs straight out behind you, with your toes on the ground.
4. Engage your core and lift your body off the ground, balancing on your forearms and toes.
5. Keep your body in a straight line from your head to your heels.
6. Hold this position for the desired amount of time.
7. Lower your body back down to the starting position.
8. Repeat for the desired number of repetitions.', source_id = '2135' WHERE id = 'ex_forearm_plank';
DELETE FROM exercises WHERE id = 'ex_db_2135' AND id NOT IN (SELECT exercise_id FROM workout_set_logs) AND id NOT IN (SELECT exercise_id FROM routine_exercises);
UPDATE exercises SET gif_url = '/gifs/0274.gif', target_muscles = 'شکم', secondary_muscles = 'خم‌کننده ران', muscles_primary = 'abs', muscles_secondary = 'hip-flexors', instructions_en = '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engage your abs and lift your shoulders off the ground, curling forward towards your knees.
4. Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.
5. Repeat for the desired number of repetitions.', source_id = '0274' WHERE id = 'ex_floor_crunch';
DELETE FROM exercises WHERE id = 'ex_db_0274' AND id NOT IN (SELECT exercise_id FROM workout_set_logs) AND id NOT IN (SELECT exercise_id FROM routine_exercises);
UPDATE exercises SET gif_url = '/gifs/0175.gif', target_muscles = 'شکم', secondary_muscles = 'پهلوها', muscles_primary = 'abs', muscles_secondary = 'obliques', instructions_en = '1. Attach a rope handle to a high pulley and kneel down facing away from the machine.
2. Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.
3. Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.
4. Pause for a moment at the bottom, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', source_id = '0175' WHERE id = 'ex_kneeling_cable_crunch';
DELETE FROM exercises WHERE id = 'ex_db_0175' AND id NOT IN (SELECT exercise_id FROM workout_set_logs) AND id NOT IN (SELECT exercise_id FROM routine_exercises);
UPDATE exercises SET gif_url = '/gifs/0687.gif', target_muscles = 'شکم', secondary_muscles = 'پهلوها', muscles_primary = 'abs', muscles_secondary = 'obliques', instructions_en = '1. Sit on the ground with your knees bent and feet flat on the floor.
2. Lean back slightly while keeping your back straight and your core engaged.
3. Hold your hands together in front of your chest or hold a weight if desired.
4. Lift your feet off the ground, balancing on your sit bones.
5. Twist your torso to the right, bringing your hands or weight towards the right side of your body.
6. Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.
7. Continue alternating sides for the desired number of repetitions.', source_id = '0687' WHERE id = 'ex_russian_twist';
DELETE FROM exercises WHERE id = 'ex_db_0687' AND id NOT IN (SELECT exercise_id FROM workout_set_logs) AND id NOT IN (SELECT exercise_id FROM routine_exercises);
UPDATE exercises SET gif_url = '/gifs/0857.gif', target_muscles = 'شکم', secondary_muscles = 'پایین کمر', muscles_primary = 'abs', muscles_secondary = 'lower-back', instructions_en = '1. Kneel on the floor and place the wheel roller in front of you.
2. Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.
3. Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.
4. Continue rolling forward until your body is fully extended and your arms are overhead.
5. Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.
6. Repeat for the desired number of repetitions.', source_id = '0857' WHERE id = 'ex_ab_wheel_rollout';
DELETE FROM exercises WHERE id = 'ex_db_0857' AND id NOT IN (SELECT exercise_id FROM workout_set_logs) AND id NOT IN (SELECT exercise_id FROM routine_exercises);
UPDATE exercises SET gif_url = '/gifs/0862.gif', target_muscles = 'شکم', secondary_muscles = 'پهلوها، پایین کمر', muscles_primary = 'abs', muscles_secondary = 'obliques,lower-back', instructions_en = '1. Stand with your feet shoulder-width apart, facing the cable machine.
2. Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.
3. Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.
4. Pause for a moment at the end of the rotation, then slowly return to the starting position.
5. Repeat the rotation to the opposite side.
6. Continue alternating sides for the desired number of repetitions.', source_id = '0862' WHERE id = 'ex_cable_woodchopper';
DELETE FROM exercises WHERE id = 'ex_db_0862' AND id NOT IN (SELECT exercise_id FROM workout_set_logs) AND id NOT IN (SELECT exercise_id FROM routine_exercises);
UPDATE exercises SET gif_url = '/gifs/0003.gif', target_muscles = 'شکم', secondary_muscles = 'خم‌کننده ران', muscles_primary = 'abs', muscles_secondary = 'hip-flexors', instructions_en = '1. Lie flat on your back with your hands placed behind your head.
2. Lift your legs off the ground and bend your knees at a 90-degree angle.
3. Bring your right elbow towards your left knee while simultaneously straightening your right leg.
4. Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.
5. Continue alternating sides in a pedaling motion for the desired number of repetitions.', source_id = '0003' WHERE id = 'ex_air_bike';
DELETE FROM exercises WHERE id = 'ex_db_0003' AND id NOT IN (SELECT exercise_id FROM workout_set_logs) AND id NOT IN (SELECT exercise_id FROM routine_exercises);
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0001', 'دراز و نشست سه‌چهارم', '3/4 sit-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن عضلات شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0001.gif', 'abs', 'hip-flexors,lower-back', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0001') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0002', 'خم شدن جانبی ۴۵ درجه', '45° side bend', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را صاف کنار بدن بگیرید.
۲. با کمر صاف و میان‌تنه درگیر، تنه را آرام به یک طرف خم کنید و دست را به سمت زانو پایین ببرید.
۳. لحظه‌ای در پایین مکث کنید، سپس آرام به وضعیت شروع برگردید.
۴. حرکت را برای طرف دیگر تکرار کنید.
۵. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0002.gif', 'abs', 'obliques', '1. Stand with your feet shoulder-width apart and your arms extended straight down by your sides.
2. Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.
3. Pause for a moment at the bottom, then slowly return to the starting position.
4. Repeat on the other side.
5. Continue alternating sides for the desired number of repetitions.', '0002') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1512', 'کشش چهارسر ران در حالت چهار دست و پا', 'All fours squad stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. در حالت چهار دست و پا قرار بگیرید؛ دست‌ها دقیقاً زیر شانه‌ها و زانوها زیر لگن.
۲. یک پا را صاف به عقب ببرید، در حالی که زانو خم و پنجه پا بالا کشیده است.
۳. لگن را آرام به سمت زمین پایین بیاورید تا کشش را در جلوی ران حس کنید.
۴. این وضعیت را ۲۰ تا ۳۰ ثانیه نگه دارید.
۵. پا را عوض کنید و کشش را برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1512.gif', 'quadriceps', 'hamstring,gluteal', '1. Start on all fours with your hands directly under your shoulders and your knees directly under your hips.
2. Extend one leg straight back, keeping your knee bent and your foot flexed.
3. Slowly lower your hips towards the ground, feeling a stretch in your quads.
4. Hold this position for 20-30 seconds.
5. Switch legs and repeat the stretch on the other side.', '1512') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0006', 'لمس پاشنه یک در میان', 'Alternate heel touchers', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را صاف به طرفین و موازی زمین باز کنید.
۳. با درگیر کردن شکم، شانه‌ها را از زمین بلند کنید و دست راست را به سمت پاشنه راست ببرید.
۴. به وضعیت شروع برگردید و برای سمت چپ تکرار کنید و دست چپ را به سمت پاشنه چپ ببرید.
۵. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0006.gif', 'abs', 'obliques', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Extend your arms straight out to the sides, parallel to the ground.
3. Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.
4. Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.
5. Continue alternating sides for the desired number of repetitions.', '0006') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0007', 'زیربغل سیم‌کش یک در میان', 'Alternate lateral pulldown', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع', '۱. روی دستگاه سیم‌کش بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۳. کمی به عقب متمایل شوید و دستگیره‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.
۴. لحظه‌ای در اوج حرکت مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0007.gif', 'upper-back', 'biceps', '1. Sit on the cable machine with your back straight and feet flat on the ground.
2. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
3. Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.
4. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.
5. Repeat for the desired number of repetitions.', '0007') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1368', 'چرخش مچ پا', 'Ankle circles', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'تثبیت‌کننده‌های مچ پا', '۱. روی زمین بنشینید و پاها را جلوی خود صاف دراز کنید.
۲. یک پا را از زمین بلند کنید و مچ پا را به صورت دایره‌ای بچرخانید.
۳. تعداد دلخواه دور را در یک جهت انجام دهید، سپس جهت را عوض کنید.
۴. با پای دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1368.gif', 'calves', '', '1. Sit on the ground with your legs extended in front of you.
2. Lift one leg off the ground and rotate your ankle in a circular motion.
3. Perform the desired number of circles in one direction, then switch to the other direction.
4. Repeat with the other leg.', '1368') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3293', 'بارفیکس آرچر', 'Archer pull up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. از میله بارفیکس با دست‌های از رو و کمی بازتر از عرض شانه آویزان شوید.
۲. میان‌تنه را درگیر کنید و کتف‌ها را به پایین و عقب بکشید.
۳. همزمان با بالا کشیدن بدن، یک دست را خم کنید و آرنج را به کنار بدن بیاورید، در حالی که دست دیگر صاف می‌ماند.
۴. تا جایی بالا بروید که چانه بالای میله قرار بگیرد و دست خم‌شده کاملاً جمع شود.
۵. با کنترل پایین بیایید، دست خم‌شده را صاف کنید و حرکت را برای طرف دیگر تکرار کنید.
۶. در هر تکرار طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3293.gif', 'upper-back', 'biceps,forearm', '1. Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.
2. Engage your core and pull your shoulder blades down and back.
3. As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.
4. Continue pulling until your chin is above the bar and your bent arm is fully flexed.
5. Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.
6. Alternate sides with each repetition.', '3293') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3294', 'شنا سوئدی آرچر', 'Archer push up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها، میان‌تنه', '۱. در وضعیت شنا قرار بگیرید و دست‌ها را کمی بازتر از عرض شانه بگذارید.
۲. یک دست را صاف به طرف و موازی زمین باز کنید.
۳. با خم کردن آرنج‌ها بدن را پایین ببرید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۴. بدن را به وضعیت شروع بالا برگردانید.
۵. برای طرف دیگر تکرار کنید و دست مخالف را به طرف باز کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3294.gif', 'chest', 'triceps,deltoids,abs', '1. Start in a push-up position with your hands slightly wider than shoulder-width apart.
2. Extend one arm straight out to the side, parallel to the ground.
3. Lower your body by bending your elbows, keeping your back straight and core engaged.
4. Push back up to the starting position.
5. Repeat on the other side, extending the opposite arm out to the side.
6. Continue alternating sides for the desired number of repetitions.', '3294') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2355', 'آویزان با زانوی خم و تاب دادن پاها', 'Arm slingers hanging bent knee legs', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، پشت', '۱. از میله بارفیکس با دست‌های کاملاً باز آویزان شوید و زانوها را ۹۰ درجه خم کنید.
۲. میان‌تنه را درگیر کنید و زانوها را به سمت سینه بالا بیاورید تا جای ممکن به آرنج‌ها نزدیک شوند.
۳. پاها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2355.gif', 'abs', 'deltoids,upper-back', '1. Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.
2. Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.
3. Slowly lower your legs back down to the starting position.
4. Repeat for the desired number of repetitions.', '2355') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2333', 'آویزان با پای صاف و تاب دادن پاها', 'Arm slingers hanging straight legs', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، پشت', '۱. از میله بارفیکس با دست‌های کاملاً باز و پاهای صاف آویزان شوید.
۲. میان‌تنه را درگیر کنید و پاها را جلوی بدن بالا بیاورید تا موازی زمین شوند.
۳. لحظه‌ای در بالا نگه دارید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2333.gif', 'abs', 'deltoids,upper-back', '1. Hang from a pull-up bar with your arms fully extended and your legs straight down.
2. Engage your core and lift your legs up in front of you until they are parallel to the ground.
3. Hold for a moment at the top, then slowly lower your legs back down to the starting position.
4. Repeat for the desired number of repetitions.', '2333') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3214', 'لمس پنجه پا با چرخش دست‌ها', 'Arms apart circular toe touch (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را به طرفین باز کنید.
۲. با پاهای صاف از کمر به جلو خم شوید و دست راست را به سمت پنجه پاها ببرید.
۳. همزمان با پایین رفتن، پای چپ را صاف به عقب بالا بیاورید و تعادل را حفظ کنید.
۴. به وضعیت شروع برگردید و حرکت را با دست چپ به سمت پنجه‌ها و بالا آوردن پای راست به عقب تکرار کنید.
۵. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3214.gif', 'gluteal', 'hamstring,quadriceps,calves', '1. Stand with your feet shoulder-width apart and arms extended to the sides.
2. Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.
3. As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.
4. Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.
5. Continue alternating sides for the desired number of repetitions.', '3214') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3204', 'دراز و نشست کامل با دست‌های بالای سر', 'Arms overhead full sit-up (male)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را صاف بالای سر دراز کنید.
۳. با درگیر کردن شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه عمود شود.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3204.gif', 'abs', 'hip-flexors,lower-back', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Extend your arms overhead, keeping them straight.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3204') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0009', 'دیپ سینه با کمک (زانو زده)', 'Assisted chest dip (kneeling)', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. دستگاه را روی ارتفاع دلخواه تنظیم کنید و زانوها را روی پد محکم قرار دهید.
۲. دستگیره‌ها را با کف دست رو به پایین و دست‌های کاملاً صاف بگیرید.
۳. با خم کردن آرنج‌ها بدن را پایین ببرید تا بازوها موازی زمین شوند.
۴. لحظه‌ای مکث کنید، سپس بدن را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0009.gif', 'chest', 'triceps,deltoids', '1. Adjust the machine to your desired height and secure your knees on the pad.
2. Grasp the handles with your palms facing down and your arms fully extended.
3. Lower your body by bending your elbows until your upper arms are parallel to the floor.
4. Pause for a moment, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '0009') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0011', 'بالا آوردن زانو در حالت آویزان با کمک', 'Assisted hanging knee raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. از میله بارفیکس با دست‌های کاملاً باز و کف دست رو به جلو آویزان شوید.
۲. عضلات میان‌تنه را درگیر کنید و با خم کردن لگن و زانوها، زانوها را به سمت سینه بالا بیاورید.
۳. لحظه‌ای در اوج حرکت مکث کنید و شکم را منقبض کنید.
۴. پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0011.gif', 'abs', 'hip-flexors', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.
3. Pause for a moment at the top of the movement, squeezing your abs.
4. Slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0011') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0010', 'بالا آوردن زانو در حالت آویزان با کمک و پرتاب به پایین', 'Assisted hanging knee raise with throw down', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. از میله بارفیکس با دست‌های کاملاً باز و کف دست رو به جلو آویزان شوید.
۲. میان‌تنه را درگیر کنید و زانوها را با پاهای جفت به سمت سینه بالا بیاورید.
۳. وقتی زانوها به سطح سینه رسیدند، پاها را با قدرت به سمت زمین پرتاب کنید و کاملاً صاف کنید.
۴. اجازه دهید پاها دوباره بالا بیایند و حرکت را به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0010.gif', 'abs', 'hip-flexors,lower-back', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your knees towards your chest, keeping your legs together.
3. Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.
4. Allow your legs to swing back up and repeat the movement for the desired number of repetitions.', '0010') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1708', 'کشش ساق پا خوابیده با کمک', 'Assisted lying calves stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'همسترینگ (پشت ران)', '۱. به پشت دراز بکشید و پاها را صاف کنید.
۲. یک زانو را خم کنید و کف پا را روی زمین بگذارید.
۳. با دست یا حوله، پنجه پا را آرام به سمت بدن بکشید تا کشش را در ساق پا حس کنید.
۴. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۵. کشش را رها کنید و با پای دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1708.gif', 'calves', 'hamstring', '1. Lie on your back with your legs extended.
2. Bend one knee and place your foot flat on the ground.
3. Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.
4. Hold the stretch for 20-30 seconds.
5. Release the stretch and repeat on the other leg.', '1708') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1709', 'کشش سرینی خوابیده با کمک', 'Assisted lying glutes stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)', '۱. به پشت دراز بکشید و پاها را صاف کنید.
۲. زانوی راست را خم کنید و مچ پای راست را روی ران چپ، کمی بالاتر از زانو بگذارید.
۳. ران چپ را با هر دو دست بگیرید و آرام به سمت سینه بکشید.
۴. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۵. رها کنید و برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1709.gif', 'gluteal', 'hamstring', '1. Lie on your back with your legs extended.
2. Bend your right knee and place your right ankle on your left thigh, just above the knee.
3. Grasp your left thigh with both hands and gently pull it towards your chest.
4. Hold the stretch for 20-30 seconds.
5. Release and repeat on the other side.', '1709') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
