INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0012', 'بالا آوردن پا خوابیده با کمک و پرتاب جانبی', 'Assisted lying leg raise with lateral throw down', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پهلوها', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها کنار بدن باشد.
۲. دست‌ها را برای حمایت زیر باسن بگذارید.
۳. شکم را درگیر کنید و پاها را صاف از زمین بلند کنید.
۴. با پاهای جفت، آن‌ها را به یک طرف پایین ببرید تا چند سانتی‌متر بالاتر از زمین قرار بگیرند.
۵. لحظه‌ای مکث کنید، سپس پاها را به وضعیت شروع برگردانید.
۶. حرکت را به طرف دیگر تکرار کنید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0012.gif', 'abs', 'hip-flexors,obliques', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Place your hands under your glutes for support.
3. Engage your abs and lift your legs off the ground, keeping them straight.
