INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0013', 'بالا آوردن پا خوابیده با کمک و پرتاب به پایین', 'Assisted lying leg raise with throw down', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، چهارسر ران', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها کنار بدن باشد.
۲. دست‌ها را برای حمایت زیر باسن بگذارید.
۳. میان‌تنه را درگیر کنید و پاها را صاف از زمین بلند کنید.
۴. پاها را تا جایی بالا بیاورید که عمود بر زمین شوند.
۵. پاها را به وضعیت شروع پایین بیاورید.
۶. همزمان پاها را صاف به سمت زمین پرتاب کنید.
۷. پاها را دوباره به وضعیت شروع بالا بیاورید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0013.gif', 'abs', 'hip-flexors,quadriceps', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Place your hands under your glutes for support.
3. Engage your core and lift your legs off the ground, keeping them straight.
4. Raise your legs until they are perpendicular to the ground.
5. Lower your legs back down to the starting position.
6. Simultaneously, throw your legs down towards the ground, keeping them straight.
7. Raise your legs back up to the starting position.
8. Repeat for the desired number of repetitions.', '0013') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0014', 'چرخش روسی با کمک', 'Assisted motion russian twist', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پهلوها، پایین کمر', '۱. روی زمین بنشینید، زانوها خم و کف پاها روی زمین باشد.
۲. توپ طبی را با دو دست جلوی سینه نگه دارید.
۳. کمی به عقب متمایل شوید، شکم را درگیر و کمر را صاف نگه دارید.
۴. تنه را آرام به راست بچرخانید و توپ طبی را به سمت راست بدن ببرید.
۵. لحظه‌ای مکث کنید، سپس تنه را به چپ بچرخانید و توپ را به سمت چپ بدن ببرید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0014.gif', 'abs', 'obliques,lower-back', '1. Sit on the ground with your knees bent and feet flat on the floor.
2. Hold the medicine ball with both hands in front of your chest.
3. Lean back slightly, engaging your abs and keeping your back straight.
4. Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.
5. Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.
6. Continue alternating sides for the desired number of repetitions.', '0014') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0015', 'بارفیکس دست جمع موازی با کمک', 'Assisted parallel close grip pull-up', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'زیربغل', 'جلو بازو، ساعد', '۱. دستگاه را روی وزن و ارتفاع دلخواه تنظیم کنید.
۲. دست‌ها را با فاصله کم و کف دست‌ها رو به هم روی میله‌های موازی بگذارید.
۳. با دست‌های کاملاً صاف و پاهای جدا از زمین از میله‌ها آویزان شوید.
۴. عضلات پشت را درگیر کنید و بدن را به سمت میله‌ها بالا بکشید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. تا جایی بالا بروید که چانه بالای میله‌ها قرار بگیرد.
۶. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0015.gif', 'upper-back', 'biceps,forearm', '1. Adjust the machine to your desired weight and height.
2. Place your hands on the parallel bars with a close grip, palms facing each other.
3. Hang from the bars with your arms fully extended and your feet off the ground.
4. Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.
5. Continue pulling until your chin is above the bars.
6. Pause for a moment at the top, then slowly lower your body back down to the starting position.
7. Repeat for the desired number of repetitions.', '0015') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0016', 'کشش همسترینگ دمر با کمک', 'Assisted prone hamstring', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)، پایین کمر', '۱. روی تشک یا نیمکت دمر دراز بکشید و پاها را کاملاً صاف کنید.
۲. از یک همراه یا کش مقاومتی برای ثابت نگه داشتن مچ پاها کمک بگیرید.
۳. عضلات همسترینگ را درگیر کنید و پاها را با زانوی صاف به سمت باسن بالا بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0016.gif', 'hamstring', 'gluteal,lower-back', '1. Lie face down on a mat or bench with your legs fully extended.
2. Have a partner or use a resistance band to secure your ankles.
3. Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0016') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1713', 'کشش چهارسر ران دمر با کمک', 'Assisted prone lying quads stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. روی زمین دمر دراز بکشید و پاها را صاف کنید.
۲. زانوی چپ را خم کنید و با دست چپ از پشت پا یا مچ پای چپ را بگیرید.
۳. پای چپ را آرام به سمت باسن بکشید تا کشش را در جلوی ران چپ حس کنید.
۴. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید و سپس رها کنید.
۵. با پای راست تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1713.gif', 'quadriceps', 'hamstring,gluteal', '1. Lie face down on the ground with your legs extended.
2. Bend your left knee and reach back with your left hand to grab your left foot or ankle.
3. Gently pull your left foot towards your glutes, feeling a stretch in your left quad.
4. Hold the stretch for 20-30 seconds, then release.
5. Repeat with your right leg.', '1713') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1714', 'کشش راست رانی دمر با کمک', 'Assisted prone rectus femoris stretch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'چهارسر ران', '۱. روی زمین دمر دراز بکشید و پاها را صاف نگه دارید.
۲. زانوی راست را خم کنید و با دست راست از پشت پا یا مچ پای راست را بگیرید.
۳. پا یا مچ پای راست را آرام به سمت باسن بکشید تا کشش را در جلوی ران راست حس کنید.
۴. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۵. رها کنید و برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1714.gif', 'abs', 'quadriceps', '1. Lie face down on the ground with your legs straight.
2. Bend your right knee and reach back with your right hand to grab your right foot or ankle.
3. Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.
4. Hold the stretch for 20-30 seconds.
5. Release and repeat on the other side.', '1714') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0017', 'بارفیکس با کمک', 'Assisted pull-up', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'زیربغل', 'جلو بازو، ساعد', '۱. دستگاه را روی وزن و ارتفاع دلخواه تنظیم کنید.
۲. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۳. با دست‌های کاملاً صاف و پاهای جدا از زمین آویزان شوید.
۴. عضلات پشت را درگیر کنید و بدن را به سمت دستگیره‌ها بالا بکشید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. تا جایی بالا بروید که چانه بالای دستگیره‌ها قرار بگیرد.
۶. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0017.gif', 'upper-back', 'biceps,forearm', '1. Adjust the machine to your desired weight and height settings.
2. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
3. Hang with your arms fully extended and your feet off the ground.
4. Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.
5. Continue pulling until your chin is above the handles.
6. Pause for a moment at the top, then slowly lower your body back down to the starting position.
7. Repeat for the desired number of repetitions.', '0017') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1716', 'کشش سینه‌ای بزرگ نشسته با توپ تعادلی', 'Assisted seated pectoralis major stretch with stability ball', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'شانه‌ها، پشت بازو', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. توپ تعادلی را با دو دست بگیرید و دست‌ها را صاف جلوی بدن دراز کنید.
۳. توپ را آرام به سمت سینه پایین بیاورید تا کشش را در عضلات سینه حس کنید.
۴. کشش را چند ثانیه نگه دارید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1716.gif', 'chest', 'deltoids,triceps', '1. Sit on a stability ball with your feet flat on the ground and your back straight.
2. Hold a stability ball with both hands and extend your arms straight out in front of you.
3. Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.
4. Hold the stretch for a few seconds, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '1716') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1712', 'کشش نزدیک‌کننده ران خوابیده به پهلو با کمک', 'Assisted side lying adductor stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'نزدیک‌کننده ران', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. به پهلو دراز بکشید و پاها را صاف و روی هم قرار دهید.
۲. برای ثبات، پای زیرین را کمی خم کنید.
۳. پای رویی را روی یک سطح محکم مانند نیمکت یا پله بگذارید.
۴. با پای رویی صاف، آن را آرام به سمت زمین پایین بیاورید تا کشش را در داخل ران حس کنید.
۵. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۶. به وضعیت شروع برگردید و برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1712.gif', 'adductors', 'hamstring,gluteal', '1. Lie on your side with your legs straight and stacked on top of each other.
2. Bend your bottom leg slightly for stability.
3. Place your top foot on a stable surface, such as a bench or step.
4. Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.
5. Hold the stretch for 20-30 seconds.
6. Return to the starting position and repeat on the other side.', '1712') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1758', 'دراز و نشست با کمک', 'Assisted sit-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. لبه نیمکت بنشینید یا از کسی بخواهید پاهای شما را نگه دارد.
۲. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۳. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۴. با درگیر کردن عضلات شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۵. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1758.gif', 'abs', 'hip-flexors', '1. Sit on the edge of a bench or have someone hold your feet down.
2. Lie flat on your back with your knees bent and feet flat on the ground.
3. Place your hands behind your head with your elbows pointing outwards.
4. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
5. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
6. Repeat for the desired number of repetitions.', '1758') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1431', 'بارفیکس دست‌برعکس ایستاده با کمک', 'Assisted standing chin-up', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'زیربغل', 'جلو بازو، ساعد', '۱. دستگاه را روی میزان کمک دلخواه تنظیم کنید.
۲. روی سکوی پا بایستید و دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۳. سینه را بالا و شانه‌ها را عقب نگه دارید، میان‌تنه را درگیر کنید و زانوها را کمی خم کنید.
۴. با خم کردن آرنج‌ها و کشیدن آن‌ها به سمت پایین و کنار بدن، خود را بالا بکشید.
۵. تا جایی بالا بروید که چانه بالای میله قرار بگیرد.
۶. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1431.gif', 'upper-back', 'biceps,forearm', '1. Adjust the machine to your desired assistance level.
2. Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.
3. Keep your chest up and shoulders back, engage your core, and slightly bend your knees.
4. Pull your body up by flexing your elbows and driving your elbows down towards your sides.
5. Continue pulling until your chin is above the bar.
6. Pause for a moment at the top, then slowly lower your body back down to the starting position.
7. Repeat for the desired number of repetitions.', '1431') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1432', 'بارفیکس ایستاده با کمک', 'Assisted standing pull-up', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'زیربغل', 'جلو بازو، ساعد', '۱. دستگاه را روی وزن و ارتفاع دلخواه تنظیم کنید.
۲. رو به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۴. عضلات زیربغل و جلو بازو را درگیر کنید و خود را به سمت دستگیره‌ها بالا بکشید.
۵. لحظه‌ای در بالا مکث کنید و عضلات پشت را منقبض کنید.
۶. آرام به وضعیت شروع پایین بیایید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1432.gif', 'upper-back', 'biceps,forearm', '1. Adjust the machine to your desired weight and height settings.
2. Stand facing the machine with your feet shoulder-width apart.
3. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
4. Engage your lats and biceps, and pull yourself up towards the handles.
5. Pause for a moment at the top, squeezing your back muscles.
6. Slowly lower yourself back down to the starting position.
7. Repeat for the desired number of repetitions.', '1432') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0018', 'پشت بازو ایستاده با کمک حوله', 'Assisted standing triceps extension (with towel)', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و حوله‌ای را با دو دست پشت سر نگه دارید.
۲. آرنج‌ها را نزدیک گوش‌ها و بازوها را ثابت نگه دارید.
۳. ساعدها را آرام به سمت بالا صاف کنید و در بالا پشت بازو را منقبض کنید.
۴. لحظه‌ای مکث کنید، سپس حوله را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0018.gif', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.
2. Keep your elbows close to your ears and your upper arms stationary.
3. Slowly extend your forearms upward, squeezing your triceps at the top.
4. Pause for a moment, then slowly lower the towel back down to the starting position.
5. Repeat for the desired number of repetitions.', '0018') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0019', 'دیپ پشت بازو با کمک (زانو زده)', 'Assisted triceps dip (kneeling)', 'arms', 'بازو', 'machine', 'دستگاه', 'پشت بازو', 'سینه، شانه‌ها', '۱. دستگاه را روی وزن و ارتفاع دلخواه تنظیم کنید.
۲. رو به دستگاه روی پد زانو بزنید و دستگیره‌ها را بگیرید.
۳. با خم کردن آرنج‌ها بدن را پایین ببرید و کمر را صاف و نزدیک دستگاه نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0019.gif', 'triceps', 'chest,deltoids', '1. Adjust the machine to your desired weight and height.
2. Kneel down on the pad facing the machine, with your hands gripping the handles.
3. Lower your body by bending your elbows, keeping your back straight and close to the machine.
4. Pause for a moment at the bottom, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '0019') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2364', 'دیپ سینه دست باز با کمک (زانو زده)', 'Assisted wide-grip chest dip (kneeling)', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. دستگاه را روی ارتفاع دلخواه تنظیم کنید و زانوها را روی پد محکم قرار دهید.
۲. دستگیره‌ها را باز بگیرید و آرنج‌ها را کمی خم نگه دارید.
۳. با خم کردن آرنج‌ها بدن را پایین ببرید تا بازوها موازی زمین شوند.
۴. با صاف کردن دست‌ها، خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2364.gif', 'chest', 'triceps,deltoids', '1. Adjust the machine to your desired height and secure your knees on the pad.
2. Grasp the handles with a wide grip and keep your elbows slightly bent.
3. Lower your body by bending your elbows until your upper arms are parallel to the floor.
4. Push yourself back up to the starting position by extending your arms.
5. Repeat for the desired number of repetitions.', '2364') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1314', 'فیله کمر روی توپ تعادلی', 'Back extension on exercise ball', 'back', 'پشت و زیربغل', 'other', 'سایر', 'فیله کمر', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. توپ تعادلی را روی زمین بگذارید و دمر روی آن دراز بکشید؛ لگن روی توپ و کف پاها به دیوار یا سطحی محکم تکیه داشته باشد.
۲. دست‌ها را پشت سر یا ضربدری روی سینه بگذارید.
۳. میان‌تنه را درگیر کنید و بالاتنه را آرام از روی توپ بلند کنید و کمر را باز کنید تا بدن از سر تا پاشنه در یک خط صاف قرار بگیرد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1314.gif', 'lower-back', 'gluteal,hamstring', '1. Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.
2. Position your hands behind your head or crossed over your chest.
3. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '1314') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3297', 'بک لیور', 'Back lever', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، ساعد، میان‌تنه', '۱. از میله بارفیکس با دست‌های از رو و کمی بازتر از عرض شانه آویزان شوید.
۲. میان‌تنه را درگیر کنید و کتف‌ها را به پایین و عقب بکشید.
۳. زانوها را خم کنید و به سمت سینه جمع کنید.
۴. پاها را صاف و آرام بالا بیاورید تا بدن موازی زمین شود.
۵. این وضعیت را چند ثانیه نگه دارید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3297.gif', 'upper-back', 'biceps,forearm,abs', '1. Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.
2. Engage your core and pull your shoulder blades down and back.
3. Bend your knees and tuck them towards your chest.
4. Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.
5. Hold this position for a few seconds, then slowly lower your legs back down to the starting position.
6. Repeat for the desired number of repetitions.', '3297') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1405', 'کشش سینه از پشت', 'Back pec stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'شانه‌ها، سینه', '۱. صاف بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دست‌ها را صاف جلوی بدن و موازی زمین دراز کنید.
۳. دست‌ها را جلوی بدن ضربدری کنید، دست راست روی دست چپ.
۴. انگشتان را در هم قفل کنید و کف دست‌ها را رو به بیرون بچرخانید.
۵. دست‌ها را آرام بالا و دور از بدن ببرید تا کشش را در پشت و سینه حس کنید.
۶. کشش را ۱۵ تا ۳۰ ثانیه نگه دارید و سپس رها کنید.
۷. برای طرف مقابل تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1405.gif', 'upper-back', 'deltoids,chest', '1. Stand tall with your feet shoulder-width apart.
2. Extend your arms straight out in front of you, parallel to the ground.
3. Cross your arms in front of your body, with your right arm over your left arm.
4. Interlock your fingers and rotate your palms away from your body.
5. Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.
6. Hold the stretch for 15-30 seconds, then release.
7. Repeat on the opposite side.', '1405') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1473', 'پرش به عقب', 'Backward jump', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'همسترینگ (پشت ران)، سرینی (باسن)، ساق پا', '۱. بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. زانوها را کمی خم کنید و با فشار هر دو پا به عقب بپرید.
۳. نرم روی پنجه پاها فرود بیایید و برای جذب ضربه زانوها را خم کنید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1473.gif', 'quadriceps', 'hamstring,gluteal,calves', '1. Stand with your feet shoulder-width apart.
2. Bend your knees slightly and jump backwards, pushing off with both feet.
3. Land softly on the balls of your feet, bending your knees to absorb the impact.
4. Repeat for the desired number of repetitions.', '1473') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0020', 'تخته تعادل', 'Balance board', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'ساق پا، همسترینگ (پشت ران)، سرینی (باسن)', '۱. تخته تعادل را روی سطح صاف بگذارید.
۲. با یک پا روی تخته تعادل بروید و مطمئن شوید پا در مرکز قرار دارد.
۳. وزن را آرام روی پای روی تخته منتقل کنید و میان‌تنه را درگیر نگه دارید.
۴. تعادل و ثبات خود را حفظ کنید و وضعیت را برای مدت دلخواه نگه دارید.
۵. تمرین را با پای دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0020.gif', 'quadriceps', 'calves,hamstring,gluteal', '1. Place the balance board on a flat surface.
2. Step onto the balance board with one foot, ensuring it is centered.
3. Slowly shift your weight onto the foot on the balance board, keeping your core engaged.
4. Maintain your balance and stability as you hold the position for a desired amount of time.
5. Repeat the exercise with the other foot.', '0020') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0968', 'جلو بازو یک در میان با کش', 'Band alternating biceps curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را از زیر با کف دست رو به بالا بگیرید.
۲. آرنج‌ها را کنار بدن نگه دارید و یک دست را آرام به سمت شانه خم کنید و در بالا جلو بازو را منقبض کنید.
۳. دست را به وضعیت شروع پایین بیاورید و با دست دیگر تکرار کنید.
۴. به تعداد تکرار دلخواه، دست‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0968.gif', 'biceps', 'forearm', '1. Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.
2. Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.
3. Lower the arm back down to the starting position and repeat with the other arm.
4. Continue alternating arms for the desired number of repetitions.', '0968') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0969', 'وی‌آپ یک در میان با کش', 'Band alternating v-up', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها بالای سر کش را نگه دارند.
۲. شکم را درگیر کنید و همزمان پاها و بالاتنه را از زمین بلند کنید و دست‌ها را به سمت پنجه پاها ببرید.
۳. هنگام پایین آوردن پاها و بالاتنه، جای پاها را عوض کنید و یکی را از روی دیگری رد کنید.
۴. حرکت را تکرار کنید و در هر تکرار جای پاها را عوض کنید.
۵. به تعداد تکرار دلخواه ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0969.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your legs straight and your arms extended overhead, holding the band.
2. Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.
3. As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.
4. Repeat the movement, alternating the position of your legs with each repetition.
5. Continue for the desired number of repetitions.', '0969') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0970', 'بارفیکس با کمک کش', 'Band assisted pull-up', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'جلو بازو، ساعد', '۱. کش را به میله بارفیکس یا یک تکیه‌گاه محکم وصل کنید.
۲. روی کش بروید و میله را با کف دست رو به جلو و کمی بازتر از عرض شانه بگیرید.
۳. با دست‌های کاملاً صاف آویزان شوید، میان‌تنه را درگیر و شانه‌ها را پایین و عقب نگه دارید.
۴. با فشردن کتف‌ها به هم و کشیدن آرنج‌ها به سمت لگن، بدن را به سمت میله بالا بکشید.
۵. تا جایی بالا بروید که چانه بالای میله باشد، سپس آرام به وضعیت شروع پایین بیایید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0970.gif', 'upper-back', 'biceps,forearm', '1. Attach the band to a pull-up bar or sturdy anchor point.
2. Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.
3. Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.
4. Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.
5. Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.
6. Repeat for the desired number of repetitions.', '0970') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0971', 'چرخ شکم با کمک کش', 'Band assisted wheel rollerout', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پایین کمر', '۱. روی زمین زانو بزنید و دستگیره‌های کش را با هر دو دست و کف دست رو به پایین بگیرید.
۲. کش را جلوی خود روی زمین بگذارید و دست‌ها را به اندازه عرض شانه قرار دهید.
۳. میان‌تنه را درگیر کنید و چرخ را آرام به جلو بغلتانید و بدن را تا جایی که کنترل دارید باز کنید.
۴. لحظه‌ای در دورترین نقطه مکث کنید، سپس چرخ را آرام به سمت زانوها برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0971.gif', 'abs', 'lower-back', '1. Kneel on the floor and hold the handles of the band with both hands, palms facing down.
2. Place the band on the ground in front of you and position your hands shoulder-width apart.
3. Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.
4. Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.
5. Repeat for the desired number of repetitions.', '0971') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1254', 'پرس سینه با کش', 'Band bench press', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'پشت بازو، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. دستگیره‌های کش را از رو و کمی بازتر از عرض شانه بگیرید.
۳. دست‌ها را کاملاً صاف کنید و کش را از سینه دور کنید.
۴. کش را آرام به سمت سینه پایین بیاورید و آرنج‌ها را در زاویه ۹۰ درجه نگه دارید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1254.gif', 'chest', 'triceps,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.
3. Extend your arms fully, pushing the bands away from your chest.
4. Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.
5. Repeat for the desired number of repetitions.', '1254') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0980', 'باز کردن لگن خم‌شده با کش', 'Band bent-over hip extension', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. کش را به یک تکیه‌گاه محکم در ارتفاع مچ پا وصل کنید.
۲. پشت به تکیه‌گاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. یک قدم جلو بروید تا کش کشیده شود و زانوها را کمی خم نگه دارید.
۴. از لگن خم شوید و به جلو متمایل شوید و ستون فقرات را در حالت طبیعی نگه دارید.
۵. پای راست را صاف به عقب ببرید و در بالا باسن را منقبض کنید.
۶. پای راست را پایین بیاورید و با پای چپ تکرار کنید.
۷. به تعداد تکرار دلخواه، پاها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0980.gif', 'gluteal', 'hamstring,lower-back', '1. Attach the band to a sturdy anchor point at ankle height.
2. Stand facing away from the anchor point with your feet shoulder-width apart.
3. Step back to create tension in the band, keeping your knees slightly bent.
4. Hinge at the hips and lean forward, maintaining a neutral spine.
5. Extend your right leg straight back, squeezing your glutes at the top.
6. Lower your right leg back down and repeat with the left leg.
7. Continue alternating legs for the desired number of repetitions.', '0980') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0972', 'کرانچ دوچرخه با کش', 'Band bicycle crunch', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'خم‌کننده ران، پهلوها', '۱. به پشت صاف دراز بکشید، دست‌ها پشت سر و زانوها خم باشد.
۲. پاها را از زمین بلند کنید و زانوی راست را به سمت سینه بیاورید و همزمان تنه را بچرخانید تا آرنج چپ به زانوی راست نزدیک شود.
۳. پای راست را صاف کنید و زانوی چپ را به سمت سینه بیاورید و تنه را بچرخانید تا آرنج راست به زانوی چپ نزدیک شود.
۴. این چرخش را مانند رکاب زدن دوچرخه یکی در میان ادامه دهید و میان‌تنه را در تمام حرکت درگیر نگه دارید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0972.gif', 'abs', 'hip-flexors,obliques', '1. Lie flat on your back with your hands behind your head and your knees bent.
2. Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.
3. Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.
4. Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.
5. Repeat for the desired number of repetitions.', '0972') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0974', 'زیربغل دست جمع با کش', 'Band close-grip pulldown', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'جلو بازو، ساعد', '۱. کش را به یک تکیه‌گاه بلند مانند میله بارفیکس یا تیر محکم وصل کنید.
۲. رو به تکیه‌گاه بایستید و کش را از زیر و به اندازه عرض شانه بگیرید.
۳. یک قدم عقب بروید تا کش کشیده شود و پاها را به اندازه عرض لگن باز نگه دارید.
۴. میان‌تنه را درگیر و کمر را صاف نگه دارید و کش را به سمت سینه پایین بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در پایین حرکت مکث کنید، سپس کش را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0974.gif', 'upper-back', 'biceps,forearm', '1. Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.
2. Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.
3. Step back to create tension in the band, keeping your feet hip-width apart.
4. Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.
5. Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.
6. Repeat for the desired number of repetitions.', '0974') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0975', 'شنا سوئدی دست جمع با کش', 'Band close-grip push-up', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'سینه، شانه‌ها', '۱. یک کش را دور بازوها، کمی بالاتر از آرنج‌ها بیندازید.
۲. در وضعیت شنا قرار بگیرید؛ دست‌ها زیر شانه‌ها و بدن از سر تا پاشنه در یک خط صاف.
۳. آرنج‌ها را خم کنید و سینه را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک بدن نگه دارید.
۴. با فشار کف دست‌ها، دست‌ها را صاف کنید و به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0975.gif', 'triceps', 'chest,deltoids', '1. Place a band around your upper arms, just above the elbows.
2. Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.
3. Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.
4. Push through your palms to extend your arms and return to the starting position.
5. Repeat for the desired number of repetitions.', '0975') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0976', 'جلو بازو تمرکزی با کش', 'Band concentration curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. روی نیمکت یا صندلی بنشینید، پاها را باز کنید و کف پاها روی زمین باشد.
۲. یک سر کش را در دست بگیرید و سر دیگر آن را زیر پای همان طرف بگذارید.
۳. کمی به جلو خم شوید و آرنج را روی داخل ران، کمی بالاتر از زانو تکیه دهید.
۴. با کف دست رو به بالا، دست را آرام به سمت شانه خم کنید و بازو را ثابت نگه دارید.
۵. لحظه‌ای در بالا مکث کنید، سپس دست را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0976.gif', 'biceps', 'forearm', '1. Sit on a bench or chair with your legs spread apart and your feet flat on the ground.
2. Hold one end of the band in your hand and step on the other end with your foot on the same side.
3. Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.
4. With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.
5. Pause for a moment at the top, then slowly lower your hand back down to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '0976') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3117', 'زیربغل دست جمع با کش ثابت از پشت', 'Band fixed back close grip pulldown', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'جلو بازو، ساعد', '۱. کش را به یک نقطه ثابت بالای سر مانند میله بارفیکس یا تیر محکم وصل کنید.
۲. روی نیمکت یا صندلی رو به کش بنشینید، کف پاها روی زمین و زانوها خم باشد.
۳. کش را با دست‌های جمع و کف دست رو به خود بگیرید.
۴. کمر را صاف نگه دارید و میان‌تنه را درگیر کنید.
۵. کش را به سمت سینه پایین بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در پایین حرکت مکث کنید و انقباض زیربغل را حس کنید.
۷. کش را آرام به وضعیت شروع برگردانید و در تمام حرکت کنترل را حفظ کنید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3117.gif', 'upper-back', 'biceps,forearm', '1. Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.
2. Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.
3. Grasp the band with a close grip, palms facing towards you.
4. Keep your back straight and engage your core.
5. Pull the band down towards your chest, squeezing your shoulder blades together.
6. Pause for a moment at the bottom of the movement, feeling the contraction in your lats.
7. Slowly release the band back to the starting position, maintaining control throughout the movement.
8. Repeat for the desired number of repetitions.', '3117') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3116', 'زیربغل دست‌برعکس با کش ثابت از پشت', 'Band fixed back underhand pulldown', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. کش را به یک تکیه‌گاه محکم بالای سر وصل کنید.
۲. رو به تکیه‌گاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. کش را از زیر و کمی بازتر از عرض شانه بگیرید.
۴. یک قدم عقب بروید تا کش کشیده شود و دست‌ها کاملاً صاف بمانند.
۵. میان‌تنه را درگیر کنید و کتف‌ها را به هم فشار دهید.
۶. کش را با هدایت آرنج‌ها به سمت سینه پایین بکشید.
۷. لحظه‌ای در پایین حرکت مکث کنید و انقباض زیربغل را حس کنید.
۸. کشش کش را آرام رها کنید و به وضعیت شروع برگردید.
۹. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3116.gif', 'upper-back', 'biceps,deltoids', '1. Attach the band to a sturdy anchor point above your head.
2. Stand facing the anchor point with your feet shoulder-width apart.
3. Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.
4. Step back to create tension in the band, keeping your arms fully extended.
5. Engage your core and squeeze your shoulder blades together.
6. Pull the band down towards your chest, leading with your elbows.
7. Pause for a moment at the bottom of the movement, feeling the contraction in your lats.
8. Slowly release the tension in the band and return to the starting position.
9. Repeat for the desired number of repetitions.', '3116') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0977', 'نشر جانب و جلو با کش', 'Band front lateral raise', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'کول (ذوزنقه)، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را جلوی ران‌ها با کف دست رو به پایین نگه دارید.
۲. دست‌ها را صاف نگه دارید و کش را جلوی بدن بالا بیاورید تا دست‌ها موازی زمین شوند.
۳. لحظه‌ای در بالا مکث کنید، سپس کش را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0977.gif', 'deltoids', 'trapezius,upper-back', '1. Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.
2. Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.
3. Pause for a moment at the top, then slowly lower the band back down to the starting position.
4. Repeat for the desired number of repetitions.', '0977') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0978', 'نشر جلو با کش', 'Band front raise', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را جلوی ران‌ها با کف دست رو به پایین نگه دارید.
۲. دست‌ها را صاف نگه دارید و آرام به جلو بالا بیاورید تا موازی زمین شوند.
۳. لحظه‌ای در بالا مکث کنید، سپس دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0978.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.
2. Keep your arms straight and slowly raise them forward until they are parallel to the ground.
3. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
4. Repeat for the desired number of repetitions.', '0978') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1408', 'بالا آوردن لگن با کش', 'Band hip lift', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. به پشت دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. یک کش مقاومتی را کمی بالاتر از زانوها قرار دهید.
۳. عضلات باسن و میان‌تنه را درگیر کنید.
۴. پاشنه‌ها را به زمین فشار دهید و لگن را از زمین بلند کنید و در بالا باسن را منقبض کنید.
۵. لحظه‌ای در بالا مکث کنید، سپس لگن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1408.gif', 'gluteal', 'hamstring,quadriceps', '1. Lie on your back with your knees bent and feet flat on the ground.
2. Place a resistance band just above your knees.
3. Engage your glutes and core muscles.
4. Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.
5. Pause for a moment at the top, then slowly lower your hips back down to the starting position.
6. Repeat for the desired number of repetitions.', '1408') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0979', 'پرس پالوف افقی با کش', 'Band horizontal pallof press', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پهلوها، سرینی (باسن)', '۱. کش را به یک تکیه‌گاه محکم در ارتفاع کمر وصل کنید.
۲. عمود بر تکیه‌گاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. دستگیره کش را با هر دو دست بگیرید و از تکیه‌گاه فاصله بگیرید تا کش کشیده شود.
۴. دست‌ها را جلوی سینه بیاورید و آرنج‌ها را خم و نزدیک بدن نگه دارید.
۵. میان‌تنه را درگیر کنید و وضعیت بدن را ثابت نگه دارید.
۶. دست‌ها را صاف جلوی بدن دراز کنید و کش را از بدن دور کنید.
۷. وضعیت باز را چند ثانیه نگه دارید و روی حفظ انقباض میان‌تنه تمرکز کنید.
۸. دست‌ها را آرام به سینه برگردانید و در برابر کشش کش مقاومت کنید.
۹. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0979.gif', 'abs', 'obliques,gluteal', '1. Attach the band to a sturdy anchor point at waist height.
2. Stand perpendicular to the anchor point with your feet shoulder-width apart.
3. Grasp the band handle with both hands and step away from the anchor point to create tension in the band.
4. Bring your hands to your chest, keeping your elbows bent and close to your body.
5. Engage your core and maintain a stable stance.
6. Extend your arms straight out in front of you, pushing the band away from your body.
7. Hold the extended position for a few seconds, focusing on maintaining tension in your core.
8. Slowly bring your hands back to your chest, resisting the pull of the band.
9. Repeat for the desired number of repetitions.', '0979') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0981', 'دراز و نشست جک‌نایف با کش', 'Band jack knife sit-up', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها بالای سر کش را نگه دارند.
۲. شکم را درگیر کنید و همزمان پاها و بالاتنه را بلند کنید و دست‌ها را به سمت پاها ببرید.
۳. لحظه‌ای در بالا مکث کنید، سپس پاها و بالاتنه را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0981.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your legs straight and your arms extended overhead, holding the band.
2. Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.
3. Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.
4. Repeat for the desired number of repetitions.', '0981') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0983', 'زیربغل تک‌دست زانو زده با کش', 'Band kneeling one arm pulldown', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع', '۱. کش را به یک تکیه‌گاه محکم بالای سر وصل کنید.
۲. زانو بزنید و کش را با یک دست و کف دست رو به پایین بگیرید.
۳. دست را کاملاً بالای سر صاف کنید و آرنج را کمی خم نگه دارید.
۴. عضلات زیربغل را درگیر کنید و کش را به سمت پهلو پایین بکشید و آرنج را به دنده‌ها نزدیک کنید.
۵. لحظه‌ای در پایین مکث کنید، سپس کشش را آرام رها کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0983.gif', 'upper-back', 'biceps', '1. Attach the band to a sturdy anchor point above your head.
2. Kneel down and hold the band with one hand, palm facing down.
3. Extend your arm fully overhead, keeping your elbow slightly bent.
4. Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.
5. Pause for a moment at the bottom, then slowly release the tension and return to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '0983') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0985', 'کرانچ چرخشی زانو زده با کش', 'Band kneeling twisting crunch', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پهلوها', '۱. کش را به یک تکیه‌گاه محکم در ارتفاع کمر وصل کنید.
۲. پشت به تکیه‌گاه زانو بزنید و کش را با دو دست بگیرید و آرنج‌ها را خم و نزدیک پهلوها نگه دارید.
۳. شکم را درگیر کنید و تنه را آرام به یک طرف بچرخانید و دست‌ها را به سمت لگن مخالف ببرید.
۴. لحظه‌ای مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. حرکت را برای طرف دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0985.gif', 'abs', 'obliques', '1. Attach the band to a sturdy anchor point at waist height.
2. Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.
3. Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.
4. Pause for a moment, then slowly return to the starting position.
5. Repeat on the other side.
6. Continue alternating sides for the desired number of repetitions.', '0985') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0984', 'چرخش داخلی لگن خوابیده با کش', 'Band lying hip internal rotation', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. به پشت دراز بکشید، پاها صاف باشد و یک کش مقاومتی دور پاها حلقه شده باشد.
۲. زانوها را خم کنید و با پاهای جفت به سمت سینه بیاورید.
۳. زانوها را آرام به سمت بیرون و دور از هم بچرخانید، در حالی که پاها جفت می‌مانند.
۴. لحظه‌ای در انتهای چرخش مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0984.gif', 'gluteal', 'hamstring,quadriceps', '1. Lie on your back with your legs straight and a resistance band looped around your feet.
2. Bend your knees and bring them towards your chest, keeping your feet together.
3. Slowly rotate your knees outwards, away from each other, while keeping your feet together.
4. Pause for a moment at the end of the rotation, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '0984') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1002', 'بالا آوردن پای صاف خوابیده با کش', 'Band lying straight leg raise', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، پاها صاف و جفت باشد.
۲. کش را دور قوس کف پاها بیندازید و دو سر آن را با دست‌ها بگیرید.
۳. با درگیر کردن شکم، هر دو پا را از زمین بلند کنید تا عمود بر زمین شوند.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1002.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your legs straight and your feet together.
2. Place the band around the arches of your feet and hold the ends of the band with your hands.
3. Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '1002') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0986', 'جلو بازو بالای سر تک‌دست با کش', 'Band one arm overhead biceps curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد، شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک سر کش را زیر پا بگذارید.
۲. سر دیگر کش را با دست کاملاً صاف بالای سر و کف دست رو به جلو بگیرید.
۳. بازو را ثابت نگه دارید و ساعد را به سمت شانه خم کنید و جلو بازو را منقبض کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس ساعد را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0986.gif', 'biceps', 'forearm,deltoids', '1. Stand with your feet shoulder-width apart and place one end of the band under your foot.
2. Hold the other end of the band with your arm fully extended overhead, palm facing forward.
3. Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.
4. Pause for a moment at the top, then slowly lower your forearm back to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '0986') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0987', 'اسکوات اسپلیت تک‌پا تک‌دست با کش', 'Band one arm single leg split squat', 'legs', 'پا', 'other', 'سایر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. بایستید، پاها را به اندازه عرض لگن باز کنید و یک کش مقاومتی دور مچ پاها بیندازید.
۲. یک پا را جلو بگذارید و روی پای دیگر را روی نیمکت یا پله پشت سر قرار دهید.
۳. برای حفظ تعادل با یک دست یک تکیه‌گاه را بگیرید.
۴. پای جلو را خم کنید و بدن را به حالت اسکوات پایین ببرید و زانو را در راستای پنجه پا نگه دارید.
۵. با فشار پاشنه به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0987.gif', 'quadriceps', 'gluteal,hamstring', '1. Stand with your feet hip-width apart and place a resistance band around your ankles.
2. Extend one leg forward and rest the top of your foot on a bench or step behind you.
3. Hold onto a support with one hand for balance.
4. Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.
5. Push through your heel to return to the starting position.
6. Repeat for the desired number of repetitions, then switch legs.', '0987') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0988', 'قایقی پایین تک‌دست ایستاده با کش', 'Band one arm standing low row', 'back', 'پشت و زیربغل', 'other', 'سایر', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. کش را به یک تکیه‌گاه ثابت در ارتفاع کمر وصل کنید.
۲. رو به تکیه‌گاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. کش را با یک دست و کف دست رو به داخل بگیرید و یک قدم عقب بروید تا کش کشیده شود.
۴. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۵. کش را به سمت کمر بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در اوج حرکت مکث کنید، سپس کش را آرام به وضعیت شروع برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0988.gif', 'upper-back', 'biceps,deltoids', '1. Attach the band to a stable anchor point at waist height.
2. Stand facing the anchor point with your feet shoulder-width apart.
3. Hold the band with one hand, palm facing inward, and step back to create tension in the band.
4. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
5. Pull the band towards your waist, squeezing your shoulder blades together.
6. Pause for a moment at the top of the movement, then slowly release the band back to the starting position.
7. Repeat for the desired number of repetitions, then switch sides.', '0988') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0989', 'پرس سینه چرخشی تک‌دست با کش', 'Band one arm twisting chest press', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'شانه‌ها، پشت بازو', '۱. کش را به یک تکیه‌گاه محکم در ارتفاع سینه وصل کنید.
۲. به پهلو نسبت به تکیه‌گاه بایستید و کش را با یک دست بگیرید.
۳. از تکیه‌گاه فاصله بگیرید تا کش کشیده شود.
۴. پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۵. دستی که کش را گرفته از جلوی بدن به سمت شانه مخالف بیاورید.
۶. در حالی که کش کشیده است، دست را به جلو و دور از بدن هل دهید و صاف کنید.
۷. آرام به وضعیت شروع برگردید و به تعداد تکرار دلخواه انجام دهید.
۸. طرف را عوض کنید و تمرین را با دست دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0989.gif', 'chest', 'deltoids,triceps', '1. Attach the band to a sturdy anchor point at chest height.
2. Stand with your side facing the anchor point and grab the band with one hand.
3. Step away from the anchor point to create tension in the band.
4. Position your feet shoulder-width apart and slightly bend your knees.
5. Bring your hand holding the band across your body, towards the opposite shoulder.
6. While maintaining tension in the band, push your hand forward and away from your body, extending your arm.
7. Slowly return to the starting position and repeat for the desired number of repetitions.
8. Switch sides and repeat the exercise with the other hand.', '0989') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0990', 'قایقی نشسته چرخشی تک‌دست با کش', 'Band one arm twisting seated row', 'back', 'پشت و زیربغل', 'other', 'سایر', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. روی نیمکت یا صندلی بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. کش را با یک دست بگیرید و دست را کاملاً جلوی بدن صاف کنید.
۳. با کمر صاف، با خم کردن آرنج و فشردن کتف‌ها به هم، کش را به سمت بدن بکشید.
۴. همزمان تنه را به سمت دستی که می‌کشد بچرخانید.
۵. لحظه‌ای در بالا مکث کنید، سپس کشش کش را آرام رها کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0990.gif', 'upper-back', 'biceps,deltoids', '1. Sit on a bench or chair with your feet flat on the ground and your back straight.
2. Hold the band with one hand and extend your arm fully in front of you.
3. Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.
4. At the same time, twist your torso towards the side of the pulling arm.
5. Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.
6. Repeat for the desired number of repetitions, then switch to the other arm.', '0990') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0991', 'پول‌ترو با کش', 'Band pull through', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. یک کش مقاومتی را به تکیه‌گاهی محکم در سطح زمین وصل کنید.
۲. پشت به تکیه‌گاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. یک قدم جلو بروید تا کش کشیده شود و زانوها را کمی خم نگه دارید.
۴. از لگن خم شوید و باسن را به عقب ببرید و زانوها را کمی خم نگه دارید.
۵. تنه را پایین ببرید تا موازی زمین شود و کشش را در همسترینگ حس کنید.
۶. لگن را به جلو برانید و باسن را منقبض کنید تا به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0991.gif', 'gluteal', 'hamstring,lower-back', '1. Attach a resistance band to a sturdy anchor point at ground level.
2. Stand facing away from the anchor point with your feet shoulder-width apart.
3. Step forward to create tension in the band, keeping your knees slightly bent.
4. Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.
5. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.
6. Drive your hips forward and squeeze your glutes to return to the starting position.
7. Repeat for the desired number of repetitions.', '0991') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0992', 'دراز و نشست با فشار کش', 'Band push sit-up', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'شانه‌ها، سینه', '۱. کش را محکم به یک تکیه‌گاه ثابت وصل کنید.
۲. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۳. کش را با دو دست بگیرید و دست‌ها را صاف به سمت سقف بالا ببرید.
۴. با درگیر کردن عضلات شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۵. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0992.gif', 'abs', 'deltoids,chest', '1. Attach the band securely to a stable anchor point.
2. Lie flat on your back with your knees bent and feet flat on the ground.
3. Hold the band with both hands and extend your arms straight up towards the ceiling.
4. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
5. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
6. Repeat for the desired number of repetitions.', '0992') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0993', 'قفسه معکوس با کش', 'Band reverse fly', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'بالای پشت، کول (ذوزنقه)', '۱. کش را به یک جسم ثابت در ارتفاع سینه وصل کنید.
۲. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را با دو دست جلوی بدن بگیرید.
۳. دست‌ها را صاف نگه دارید و به طرفین بالا بیاورید تا موازی زمین شوند.
۴. در اوج حرکت کتف‌ها را به هم فشار دهید.
۵. دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0993.gif', 'deltoids', 'upper-back,trapezius', '1. Attach the band to a stationary object at chest height.
2. Stand with your feet shoulder-width apart and hold the band with both hands in front of you.
3. Keep your arms straight and lift them out to the sides until they are parallel to the ground.
4. Squeeze your shoulder blades together at the top of the movement.
5. Slowly lower your arms back to the starting position.
6. Repeat for the desired number of repetitions.', '0993') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0994', 'مچ دست معکوس با کش', 'Band reverse wrist curl', 'arms', 'بازو', 'other', 'سایر', 'ساعد', 'ساعد', '۱. روی نیمکت یا صندلی بنشینید و کف پاها را روی زمین بگذارید.
۲. کش را از رو و با کف دست رو به پایین بگیرید و دور انگشتان بپیچید.
۳. ساعدها را روی ران‌ها بگذارید و مچ‌ها از لبه آویزان باشند.
۴. مچ‌ها را آرام به سمت بالا خم کنید و ساعدها را منقبض کنید.
۵. لحظه‌ای در بالا مکث کنید، سپس مچ‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0994.gif', 'forearm', '', '1. Sit on a bench or chair with your feet flat on the ground.
2. Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.
3. Rest your forearms on your thighs, with your wrists hanging off the edge.
4. Slowly curl your wrists upward, squeezing your forearms.
5. Pause for a moment at the top, then slowly lower your wrists back down to the starting position.
6. Repeat for the desired number of repetitions.', '0994') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0996', 'چرخش داخلی لگن نشسته با کش', 'Band seated hip internal rotation', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. روی صندلی یا نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. یک کش مقاومتی دور ران‌ها، کمی بالاتر از زانوها بیندازید.
۳. زانوها را در زاویه ۹۰ درجه خم و پاها را به اندازه عرض شانه باز نگه دارید.
۴. باسن را درگیر کنید و زانوها را آرام به سمت بیرون بچرخانید و در برابر مقاومت کش فشار دهید.
۵. لحظه‌ای در انتهای حرکت مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0996.gif', 'gluteal', 'hamstring,quadriceps', '1. Sit on a chair or bench with your back straight and feet flat on the ground.
2. Place a resistance band around your thighs, just above your knees.
3. Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.
4. Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.
5. Pause for a moment at the end of the movement, then slowly return to the starting position.
6. Repeat for the desired number of repetitions.', '0996') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1011', 'چرخش تنه نشسته با کش', 'Band seated twist', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پهلوها', '۱. روی زمین بنشینید، پاها را جلوی بدن صاف کنید و کمر را صاف نگه دارید.
۲. کش را دور کمر بپیچید و دو سر آن را با دو دست بگیرید.
۳. شکم را درگیر کنید و تنه را آرام به یک طرف بچرخانید و کمر را صاف و پاها را روی زمین نگه دارید.
۴. لحظه‌ای در انتهای چرخش مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. چرخش را به طرف دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1011.gif', 'abs', 'obliques', '1. Sit on the ground with your legs extended in front of you and your back straight.
2. Wrap the band around your waist and hold the ends with both hands.
3. Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.
4. Pause for a moment at the end of the twist, then slowly return to the starting position.
5. Repeat the twist to the other side.
6. Continue alternating sides for the desired number of repetitions.', '1011') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0997', 'پرس سرشانه با کش', 'Band shoulder press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را زیر پاها بگذارید.
۲. کش را با کف دست رو به جلو بگیرید و دست‌ها را با آرنج خم تا ارتفاع شانه بالا بیاورید.
۳. کش را بالای سر پرس کنید و دست‌ها را کاملاً صاف کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس کش را آرام تا ارتفاع شانه پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0997.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and place the band under your feet.
2. Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.
3. Press the band overhead, fully extending your arms.
4. Pause for a moment at the top, then slowly lower the band back to shoulder height.
5. Repeat for the desired number of repetitions.', '0997') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1018', 'شراگ با کش', 'Band shrug', 'back', 'پشت و زیربغل', 'other', 'سایر', 'کول (ذوزنقه)', 'شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را زیر پاها بگذارید و دو سر آن را با دست‌ها بگیرید.
۲. دست‌ها را صاف و رها نگه دارید و بگذارید کش جلوی ران‌ها آویزان باشد.
۳. با بالا انداختن شانه‌ها عضلات کول را درگیر کنید و کش را تا جای ممکن بالا ببرید.
۴. انقباض را لحظه‌ای نگه دارید، سپس شانه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1018.gif', 'trapezius', 'deltoids', '1. Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.
2. Keep your arms straight and relaxed, and let the band hang in front of your thighs.
3. Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.
4. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.
5. Repeat for the desired number of repetitions.', '1018') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0998', 'پشت بازو جانبی با کش', 'Band side triceps extension', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را با دو دست و کف دست رو به پایین بگیرید.
۲. دست‌ها را صاف به طرفین و موازی زمین باز کنید.
۳. آرنج‌ها را آرام خم کنید و دست‌ها را به سمت شانه‌ها بیاورید و بازوها را ثابت نگه دارید.
۴. لحظه‌ای مکث کنید، سپس دست‌ها را آرام به وضعیت شروع باز کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0998.gif', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.
2. Extend your arms straight out to the sides, keeping them parallel to the ground.
3. Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.
4. Pause for a moment, then slowly extend your arms back out to the starting position.
5. Repeat for the desired number of repetitions.', '0998') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0999', 'ساق پا تک‌پا با کش', 'Band single leg calf raise', 'legs', 'پا', 'other', 'سایر', 'ساق پا', 'مچ پا، پاها', '۱. بایستید، پاها را به اندازه عرض لگن باز کنید و کش را دور پنجه پای چپ بیندازید.
۲. در صورت نیاز برای حفظ تعادل یک جسم ثابت را بگیرید.
۳. پاشنه پای چپ را آرام از زمین بلند کنید و وزن بدن را روی پنجه پا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاشنه چپ را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس با پای راست تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0999.gif', 'calves', '', '1. Stand with your feet hip-width apart and place the band around the ball of your left foot.
2. Hold onto a stable object for balance if needed.
3. Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.
4. Pause for a moment at the top, then slowly lower your left heel back down to the starting position.
5. Repeat for the desired number of repetitions, then switch to the right leg.', '0999') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1000', 'ساق پا معکوس تک‌پا با کش', 'Band single leg reverse calf raise', 'legs', 'پا', 'other', 'سایر', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. بایستید، پاها را به اندازه عرض لگن باز کنید و کش را دور پنجه پا بیندازید.
۲. برای حفظ تعادل یک جسم ثابت را بگیرید.
۳. پاشنه را آرام از زمین بلند کنید و وزن بدن را روی پنجه پا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاشنه را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1000.gif', 'calves', 'hamstring,gluteal', '1. Stand with your feet hip-width apart and place the band around the ball of your foot.
2. Hold onto a stable object for balance.
3. Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.
4. Pause for a moment at the top, then slowly lower your heel back down to the starting position.
5. Repeat for the desired number of repetitions, then switch to the other leg.', '1000') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1001', 'اسکوات اسپلیت تک‌پا با کش', 'Band single leg split squat', 'legs', 'پا', 'other', 'سایر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. بایستید، پاها را به اندازه عرض لگن باز کنید و یک کش مقاومتی دور مچ پاها بیندازید.
۲. با پای راست یک گام بلند به جلو و با پای چپ یک گام کوتاه‌تر به عقب بردارید.
۳. زانوها را خم کنید و بدن را پایین ببرید تا ران راست موازی زمین شود و زانوی چپ کمی بالاتر از زمین بماند.
۴. با فشار پاشنه راست به وضعیت شروع برگردید.
۵. حرکت را برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1001.gif', 'quadriceps', 'gluteal,hamstring', '1. Stand with your feet hip-width apart and place a resistance band around your ankles.
2. Take a big step forward with your right foot and a smaller step back with your left foot.
3. Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.
4. Push through your right heel to return to the starting position.
5. Repeat on the other side.', '1001') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1004', 'اسکوات با کش', 'Band squat', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را کمی بالاتر از زانوها قرار دهید.
۲. سینه را بالا و میان‌تنه را درگیر نگه دارید، لگن را به عقب ببرید و با خم کردن زانوها به حالت اسکوات پایین بروید.
۳. مطمئن شوید زانوها در راستای پنجه پا حرکت می‌کنند و وزن روی پاشنه‌هاست.
۴. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1004.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, with the band placed just above your knees.
2. Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.
3. Make sure your knees are tracking over your toes and your weight is in your heels.
4. Pause for a moment at the bottom, then push through your heels to return to the starting position.
5. Repeat for the desired number of repetitions.', '1004') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1003', 'اسکوات و قایقی با کش', 'Band squat row', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، پشت', '۱. کش را به یک تکیه‌گاه محکم در ارتفاع کمر وصل کنید.
۲. رو به تکیه‌گاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. دستگیره‌های کش را با کف دست‌های رو به هم بگیرید و دست‌ها را جلوی بدن صاف کنید.
۴. زانوها را خم کنید و به حالت اسکوات پایین بروید و کمر را صاف و سینه را بالا نگه دارید.
۵. در حالت اسکوات، دستگیره‌ها را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در بالا مکث کنید، سپس کشش را آرام رها کنید و به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1003.gif', 'gluteal', 'hamstring,quadriceps,upper-back', '1. Attach the band to a sturdy anchor point at waist height.
2. Stand facing the anchor point with your feet shoulder-width apart.
3. Hold the band handles with your palms facing each other and your arms extended in front of you.
4. Bend your knees and lower into a squat position, keeping your back straight and chest lifted.
5. From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly release the tension and return to the starting position.
7. Repeat for the desired number of repetitions.', '1003') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1005', 'کرانچ ایستاده با کش', 'Band standing crunch', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پهلوها', '۱. کش را به یک تکیه‌گاه محکم در ارتفاع کمر وصل کنید.
۲. پشت به تکیه‌گاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. کش را با دو دست بگیرید و تا جلوی سینه بالا بیاورید و آرنج‌ها را خم و نزدیک بدن نگه دارید.
۴. شکم را درگیر کنید و آرام به جلو کرانچ کنید و سینه را به سمت زانوها ببرید.
۵. لحظه‌ای در بالای کرانچ مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1005.gif', 'abs', 'obliques', '1. Attach the band to a sturdy anchor point at waist height.
2. Stand facing away from the anchor point with your feet shoulder-width apart.
3. Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.
4. Engage your abs and slowly crunch forward, bringing your chest towards your knees.
5. Pause for a moment at the top of the crunch, then slowly return to the starting position.
6. Repeat for the desired number of repetitions.', '1005') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1022', 'زیربغل دلتوئید خلفی ایستاده با کش', 'Band standing rear delt row', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع، جلو بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را زیر پاها بگذارید.
۲. دستگیره‌های کش را با کف دست‌های رو به هم بگیرید و دست‌ها را جلوی بدن صاف کنید.
۳. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۴. کش را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در بالا مکث کنید، سپس کشش را آرام رها کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1022.gif', 'deltoids', 'trapezius,upper-back,biceps', '1. Stand with your feet shoulder-width apart and place the band under your feet.
2. Hold the band handles with your palms facing each other and your arms extended in front of you.
3. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
4. Pull the band towards your chest, squeezing your shoulder blades together.
5. Pause for a moment at the top, then slowly release the tension and return to the starting position.
6. Repeat for the desired number of repetitions.', '1022') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1007', 'کرانچ چرخشی ایستاده با کش', 'Band standing twisting crunch', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پهلوها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را دور بالای کمر انداخته و جلوی سینه ضربدری کنید.
۲. دو سر کش را با دست‌ها بگیرید و آرنج‌ها را خم و نزدیک پهلوها نگه دارید.
۳. شکم را درگیر کنید و تنه را به یک طرف بچرخانید و آرنج را به سمت زانوی مخالف ببرید.
۴. لحظه‌ای مکث کنید، سپس به وضعیت شروع برگردید.
۵. حرکت را برای طرف دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1007.gif', 'abs', 'obliques', '1. Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.
2. Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.
3. Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.
4. Pause for a moment, then return to the starting position.
5. Repeat on the other side.
6. Continue alternating sides for the desired number of repetitions.', '1007') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1008', 'استپ‌آپ با کش', 'Band step-up', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. یک کش دور ران‌ها، کمی بالاتر از زانوها بیندازید.
۲. رو به پله یا سکو بایستید و پاها را به اندازه عرض لگن باز کنید.
۳. با فشار پاشنه، با پای راست روی سکو بروید.
۴. پای چپ را صاف پشت سر دراز کنید.
۵. پای چپ را دوباره روی زمین بگذارید.
۶. حرکت را با بالا رفتن پای چپ روی سکو تکرار کنید.
۷. به تعداد تکرار دلخواه، پاها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1008.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Place a band around your thighs, just above your knees.
2. Stand facing a step or platform with your feet hip-width apart.
3. Step up onto the platform with your right foot, pushing through your heel.
4. Extend your left leg behind you, keeping it straight.
5. Lower your left foot back down to the ground.
6. Repeat with your left foot stepping up onto the platform.
7. Continue alternating legs for the desired number of repetitions.', '1008') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1009', 'ددلیفت پا صاف با کش', 'Band stiff leg deadlift', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را دور مچ پاها بیندازید.
۲. کش را با دو دست جلوی ران‌ها و کف دست رو به بدن بگیرید.
۳. با کمر صاف و میان‌تنه درگیر، از لگن خم شوید و بالاتنه را آرام به سمت زمین پایین ببرید.
۴. هنگام پایین رفتن، لگن را به عقب ببرید و اجازه دهید زانوها کمی خم شوند.
۵. کش را به سمت زمین پایین ببرید و کشش را در همسترینگ حس کنید.
۶. لحظه‌ای در پایین مکث کنید، سپس با درگیر کردن باسن و همسترینگ بالاتنه را به وضعیت شروع بالا ببرید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1009.gif', 'gluteal', 'hamstring,lower-back', '1. Stand with your feet shoulder-width apart and place the band around your ankles.
2. Hold the band with both hands in front of your thighs, palms facing your body.
3. Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.
4. As you lower, push your hips back and allow your knees to bend slightly.
5. Lower the band towards the ground, feeling a stretch in your hamstrings.
6. Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.
7. Repeat for the desired number of repetitions.', '1009') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1023', 'ددلیفت پا صاف کمر صاف با کش', 'Band straight back stiff leg deadlift', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را دور ران‌ها بیندازید.
۲. کش را با دو دست جلوی ران‌ها و کف دست رو به بدن بگیرید.
۳. با کمر صاف و زانوهای کمی خم، از لگن خم شوید و کش را به سمت زمین پایین ببرید.
۴. هنگام پایین بردن کش، کشش را در همسترینگ حس کنید.
۵. با درگیر کردن باسن و همسترینگ بدن را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1023.gif', 'gluteal', 'hamstring,lower-back', '1. Stand with your feet shoulder-width apart and place the band around your upper legs.
2. Hold the band with both hands in front of your thighs, palms facing your body.
3. Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.
4. Feel the stretch in your hamstrings as you lower the band.
5. Engage your glutes and hamstrings to lift your body back up to the starting position.
6. Repeat for the desired number of repetitions.', '1023') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1010', 'ددلیفت پا مستقیم با کش', 'Band straight leg deadlift', 'back', 'پشت و زیربغل', 'other', 'سایر', 'فیله کمر', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را دور پاها بیندازید.
۲. کش را با دو دست و کف دست رو به بدن بگیرید و دست‌ها را صاف نگه دارید.
۳. میان‌تنه را درگیر کنید و زانوها را کمی خم نگه دارید.
۴. آرام از لگن به جلو خم شوید و کمر را صاف و سینه را بالا نگه دارید.
۵. با پاهای صاف، کش را به سمت زمین پایین ببرید.
۶. لحظه‌ای در پایین مکث کنید، سپس با انقباض باسن و همسترینگ به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1010.gif', 'lower-back', 'hamstring,gluteal', '1. Stand with your feet shoulder-width apart and place the band around your feet.
2. Hold the band with both hands, palms facing your body, and keep your arms straight.
3. Engage your core and maintain a slight bend in your knees.
4. Slowly hinge forward at your hips, keeping your back straight and chest lifted.
5. Lower the band towards the ground while keeping your legs straight.
6. Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.
7. Repeat for the desired number of repetitions.', '1010') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1012', 'پرس بالای سر چرخشی با کش', 'Band twisting overhead press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را زیر پاها بگذارید.
۲. دستگیره‌های کش را در ارتفاع شانه و با کف دست رو به جلو نگه دارید.
۳. میان‌تنه را درگیر کنید و کش را بالای سر پرس کنید و دست‌ها را کاملاً صاف کنید.
۴. هنگام پرس، تنه را به یک طرف بچرخانید و لگن را ثابت نگه دارید.
۵. لحظه‌ای در بالا مکث کنید، سپس به وضعیت شروع برگردید.
۶. پرس و چرخش را برای طرف مقابل تکرار کنید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1012.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and place the band under your feet.
2. Hold the band handles at shoulder height with your palms facing forward.
3. Engage your core and press the band overhead, fully extending your arms.
4. As you press, twist your torso to one side, keeping your hips stable.
5. Pause for a moment at the top, then return to the starting position.
6. Repeat the press and twist on the opposite side.
7. Continue alternating sides for the desired number of repetitions.', '1012') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1369', 'ساق پا دو پا با کش (نسخه ۲)', 'Band two legs calf raise - (band under both legs) v. 2', 'legs', 'پا', 'other', 'سایر', 'ساق پا', 'مچ پا، پاها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کش مقاومتی زیر هر دو پا بگذارید.
۲. برای ثبات دو سر کش را با دست‌ها بگیرید.
۳. با کمک عضلات ساق، پاشنه‌ها را تا جای ممکن از زمین بلند کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1369.gif', 'calves', '', '1. Stand with your feet shoulder-width apart and place a resistance band under both feet.
2. Hold the ends of the band with your hands for stability.
3. Raise your heels off the ground as high as possible, using your calves.
4. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
5. Repeat for the desired number of repetitions.', '1369') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1013', 'زیربغل دست‌برعکس با کش', 'Band underhand pulldown', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'جلو بازو، ساعد', '۱. کش را به یک تکیه‌گاه بلند مانند میله بارفیکس یا تیر محکم وصل کنید.
۲. رو به تکیه‌گاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. کش را از زیر و کمی بازتر از عرض شانه بگیرید.
۴. دست‌ها را کاملاً بالای سر صاف کنید و آرنج‌ها را کمی خم نگه دارید.
۵. زیربغل را درگیر کنید و کش را به سمت سینه پایین بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در پایین حرکت مکث کنید، سپس کشش را آرام رها کنید و به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1013.gif', 'upper-back', 'biceps,forearm', '1. Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.
2. Stand facing the anchor point with your feet shoulder-width apart.
3. Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.
4. Extend your arms fully overhead, keeping your elbows slightly bent.
5. Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.
6. Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.
7. Repeat for the desired number of repetitions.', '1013') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1014', 'وی‌آپ با کش', 'Band v-up', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها بالای سر کش را نگه دارند.
۲. با درگیر کردن شکم، همزمان پاها و بالاتنه را از زمین بلند کنید و دست‌ها را به سمت پنجه پاها ببرید.
۳. لحظه‌ای در بالا مکث کنید، سپس پاها و بالاتنه را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1014.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your legs straight and your arms extended overhead, holding the band.
2. Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.
3. Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.
4. Repeat for the desired number of repetitions.', '1014') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1015', 'پرس پالوف عمودی با کش', 'Band vertical pallof press', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پهلوها، سرینی (باسن)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را دور یک جسم محکم در ارتفاع سینه ببندید.
۲. کش را با دو دست بگیرید و از تکیه‌گاه فاصله بگیرید تا کش کشیده شود.
۳. عمود بر تکیه‌گاه بایستید، به طوری که پهلوی شما رو به کش باشد.
۴. دست‌ها را صاف جلوی بدن دراز کنید و دست‌ها را در ارتفاع سینه نگه دارید.
۵. میان‌تنه را درگیر کنید و کش را از سینه دور کنید و دست‌ها را کاملاً صاف کنید.
۶. وضعیت را چند ثانیه نگه دارید، سپس کش را آرام به سمت سینه برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1015.gif', 'abs', 'obliques,gluteal', '1. Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.
2. Hold the band with both hands and step away from the anchor point, creating tension in the band.
3. Position yourself perpendicular to the anchor point, with your side facing the band.
4. Extend your arms straight out in front of you, keeping your hands at chest height.
5. Engage your core and press the band away from your chest, fully extending your arms.
6. Hold the position for a few seconds, then slowly bring the band back towards your chest.
7. Repeat for the desired number of repetitions, then switch sides.', '1015') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1016', 'مچ دست با کش', 'Band wrist curl', 'arms', 'بازو', 'other', 'سایر', 'ساعد', 'جلو بازو، پشت بازو', '۱. روی نیمکت یا صندلی بنشینید و کف پاها را روی زمین بگذارید.
۲. کش را با دو دست و کف دست رو به بالا بگیرید و ساعدها را روی ران‌ها بگذارید.
۳. مچ‌ها را آرام به سمت بالا خم کنید و ساعدها را منقبض کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس مچ‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1016.gif', 'forearm', 'biceps,triceps', '1. Sit on a bench or chair with your feet flat on the ground.
2. Hold the band with both hands, palms facing up, and rest your forearms on your thighs.
3. Slowly curl your wrists upward, squeezing your forearms.
4. Pause for a moment at the top, then slowly lower your wrists back down to the starting position.
5. Repeat for the desired number of repetitions.', '1016') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1017', 'نشر Y با کش', 'Band y-raise', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کش را جلوی ران‌ها با کف دست رو به داخل بگیرید.
۲. دست‌ها را صاف نگه دارید و به بالا و طرفین ببرید تا بدن شکل حرف «Y» بسازد.
۳. در اوج حرکت کتف‌ها را به هم فشار دهید.
۴. دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1017.gif', 'deltoids', 'trapezius,upper-back', '1. Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.
2. Keep your arms straight and lift them up and out to the sides, forming a ''Y'' shape with your body.
3. Squeeze your shoulder blades together at the top of the movement.
4. Slowly lower your arms back down to the starting position.
5. Repeat for the desired number of repetitions.', '1017') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0023', 'جلو بازو هالتر یک در میان', 'Barbell alternate biceps curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک هالتر کوچک با کف دست رو به جلو بگیرید.
۲. بازوها را ثابت نگه دارید و با بازدم، وزنه‌ها را با انقباض جلو بازو بالا بیاورید.
۳. وزنه‌ها را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و وزنه‌ها در سطح شانه قرار بگیرند.
۴. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۵. با دم، وزنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه و یکی در میان با دو دست انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0023.gif', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.
2. Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.
3. Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.
4. Hold the contracted position for a brief pause as you squeeze your biceps.
5. Inhale as you slowly begin to lower the barbells back to the starting position.
6. Repeat for the desired number of repetitions, alternating arms.', '0023') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0024', 'اسکوات از جلو هالتر با نیمکت', 'Barbell bench front squat', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'همسترینگ (پشت ران)، سرینی (باسن)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای سینه، درست زیر ترقوه قرار دهید.
۲. هالتر را از رو بگیرید، آرنج‌ها را بالا و بازوها را موازی زمین نگه دارید.
۳. با خم کردن زانوها و لگن به حالت اسکوات پایین بروید و کمر را صاف و سینه را بالا نگه دارید.
۴. لحظه‌ای در پایین اسکوات مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0024.gif', 'quadriceps', 'hamstring,gluteal,calves', '1. Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.
2. Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.
3. Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.
4. Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.
5. Repeat for the desired number of repetitions.', '0024') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0026', 'اسکوات هالتر با نیمکت', 'Barbell bench squat', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. هالتر را روی رک اسکوات در ارتفاع سینه قرار دهید.
۲. پشت به رک بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. زانوها را خم کنید و به حالت اسکوات پایین بروید و کمر را صاف و سینه را بالا نگه دارید.
۴. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۵. هالتر را از رک بردارید و یک قدم عقب بروید و مطمئن شوید پاها همچنان به اندازه عرض شانه باز هستند.
۶. به حالت اسکوات پایین بروید و زانوها را در راستای پنجه پا نگه دارید.
۷. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0026.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Set up a barbell on a squat rack at chest height.
2. Stand facing away from the rack, with your feet shoulder-width apart.
3. Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.
4. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
5. Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.
6. Lower your body down into a squat, keeping your knees in line with your toes.
7. Pause for a moment at the bottom, then push through your heels to return to the starting position.
8. Repeat for the desired number of repetitions.', '0026') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1316', 'پول‌اور هالتر با آرنج خم', 'Barbell bent arm pullover', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'زیربغل', 'پشت بازو، سینه', '۱. روی نیمکت صاف دراز بکشید؛ سر در یک انتهای نیمکت و پاها روی زمین.
۲. هالتر را به اندازه عرض شانه بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. هالتر را با دست‌های کمی خم به پشت سر پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس هالتر را به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1316.gif', 'upper-back', 'triceps,chest', '1. Lie flat on a bench with your head at one end and your feet on the floor.
2. Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.
3. Lower the barbell behind your head while keeping your arms slightly bent.
4. Pause for a moment, then raise the barbell back to the starting position.
5. Repeat for the desired number of repetitions.', '1316') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2407', 'جلو بازو هالتر با آرم‌بلستر', 'Barbell biceps curl (with arm blaster)', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از زیر با کف دست رو به بالا بگیرید.
۲. بازوها را به آرم‌بلستر تکیه دهید و آرنج‌ها را نزدیک تنه نگه دارید.
۳. بازوها را ثابت نگه دارید و با بازدم، وزنه را با انقباض جلو بازو بالا بیاورید.
۴. هالتر را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و میله در سطح شانه باشد.
۵. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۶. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2407.gif', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.
2. Place your upper arms against the arm blaster, keeping your elbows close to your torso.
3. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
4. Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the barbell back to the starting position.
7. Repeat for the desired number of repetitions.', '2407') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0028', 'کلین و پرس هالتر', 'Barbell clean and press', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'همسترینگ (پشت ران)، سرینی (باسن)، شانه‌ها، پشت بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر روی زمین جلوی شما باشد.
۲. زانوها را خم کنید و از لگن خم شوید و هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. با فشار پاشنه‌ها و باز کردن لگن و زانوها، هالتر را از زمین بلند کنید و نزدیک بدن نگه دارید.
۴. وقتی هالتر به ران‌ها رسید، لگن را انفجاری باز کنید، شانه‌ها را بالا بیندازید و هالتر را به سمت سینه بکشید.
۵. وقتی هالتر به ارتفاع سینه رسید، سریع زیر آن بروید و آن را در سطح شانه بگیرید، آرنج‌ها رو به جلو و کف دست‌ها رو به بالا.
۶. از همین وضعیت، با صاف کردن دست‌ها هالتر را مستقیم بالای سر پرس کنید.
۷. هالتر را به وضعیت شروع پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0028.gif', 'quadriceps', 'hamstring,gluteal,deltoids,triceps', '1. Stand with your feet shoulder-width apart and the barbell on the floor in front of you.
2. Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.
4. As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.
5. As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.
6. From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.
7. Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', '0028') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0029', 'اسکوات از جلو هالتر با گرفتن کلین', 'Barbell clean-grip front squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای سینه با آرنج‌های رو به جلو قرار دهید.
۲. با خم کردن زانوها و بردن لگن به عقب، مانند نشستن روی صندلی، بدن را پایین ببرید.
۳. هنگام پایین رفتن سینه را بالا و کمر را صاف نگه دارید و مراقب باشید زانوها از پنجه پا جلوتر نروند.
۴. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۵. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها و باز کردن لگن و زانوها بایستید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0029.gif', 'gluteal', 'quadriceps,hamstring,calves,abs', '1. Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.
2. Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.
3. Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.
4. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
5. Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.
6. Repeat for the desired number of repetitions.', '0029') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0030', 'پرس سینه هالتر دست جمع', 'Barbell close-grip bench press', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. هالتر را با دست‌های جمع، کمی جمع‌تر از عرض شانه بگیرید.
۳. هالتر را از جایگاه بردارید و آرام به سمت سینه پایین بیاورید و آرنج‌ها را نزدیک بدن نگه دارید.
۴. وقتی هالتر به سینه رسید لحظه‌ای مکث کنید.
۵. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0030.gif', 'triceps', 'chest,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.
3. Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.
4. Pause for a moment when the barbell touches your chest.
5. Push the barbell back up to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '0030') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0034', 'پول‌اور هالتر آرنج خم روی نیمکت زیرسینه', 'Barbell decline bent arm pullover', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'زیربغل', 'پشت بازو، سینه', '۱. روی نیمکت زیرسینه دراز بکشید، سر پایین‌تر از لگن و پاها محکم شده باشد.
۲. هالتر را از رو (کف دست رو به جلو) بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. هالتر را با کنترل و دست‌های کمی خم به پشت سر پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس با انقباض زیربغل هالتر را به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0034.gif', 'upper-back', 'triceps,chest', '1. Lie down on a decline bench with your head lower than your hips and your feet secured.
2. Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.
3. Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.
4. Pause for a moment, then raise the barbell back to the starting position by contracting your lats.
5. Repeat for the desired number of repetitions.', '0034') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0035', 'پرس جمجمه دست جمع هالتر روی نیمکت زیرسینه', 'Barbell decline close grip to skull press', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت زیرسینه دراز بکشید، سر پایین‌تر از پاها باشد و هالتر را با دست‌های جمع بگیرید.
۲. با خم کردن آرنج‌ها هالتر را به سمت پیشانی پایین بیاورید و بازوها را ثابت نگه دارید.
۳. لحظه‌ای مکث کنید، سپس دست‌ها را صاف کنید و هالتر را به وضعیت شروع بالا ببرید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0035.gif', 'triceps', 'chest,deltoids', '1. Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.
2. Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.
3. Pause for a moment, then extend your arms to press the barbell back up to the starting position.
4. Repeat for the desired number of repetitions.', '0035') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1255', 'پول‌اور هالتر روی نیمکت زیرسینه', 'Barbell decline pullover', 'chest', 'سینه', 'barbell', 'هالتر', 'سینه', 'پشت بازو، شانه‌ها', '۱. روی نیمکت زیرسینه دراز بکشید، سر پایین‌تر از لگن و پاها محکم شده باشد.
۲. هالتر را از رو (کف دست رو به جلو) و کمی بازتر از عرض شانه بگیرید.
۳. دست‌ها را بالای سینه صاف کنید و آرنج‌ها را کمی خم نگه دارید.
۴. هالتر را در یک مسیر کمانی به پشت سر پایین ببرید و کشش را در سینه و شانه‌ها حس کنید.
۵. لحظه‌ای مکث کنید، سپس با معکوس کردن حرکت هالتر را به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1255.gif', 'chest', 'triceps,deltoids', '1. Lie down on a decline bench with your head lower than your hips and your feet secured.
2. Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.
3. Extend your arms above your chest, keeping a slight bend in your elbows.
4. Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.
5. Pause for a moment, then return the barbell to the starting position by reversing the motion.
6. Repeat for the desired number of repetitions.', '1255') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0036', 'پرس زیرسینه هالتر دست باز', 'Barbell decline wide-grip press', 'chest', 'سینه', 'barbell', 'هالتر', 'سینه', 'پشت بازو، شانه‌ها', '۱. روی نیمکت زیرسینه دراز بکشید، پاها محکم و سر پایین‌تر از لگن باشد.
۲. هالتر را باز و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را تا سینه پایین بیاورید و آرنج‌ها را به طرفین باز نگه دارید.
۴. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0036.gif', 'chest', 'triceps,deltoids', '1. Lie on a decline bench with your feet secured and your head lower than your hips.
2. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.
3. Lower the barbell to your chest, keeping your elbows out to the sides.
4. Push the barbell back up to the starting position, fully extending your arms.
5. Repeat for the desired number of repetitions.', '0036') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0037', 'پول‌اور هالتر دست باز روی نیمکت زیرسینه', 'Barbell decline wide-grip pullover', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'زیربغل', 'پشت بازو، سینه', '۱. روی نیمکت زیرسینه دراز بکشید، سر پایین‌تر از لگن و پاها محکم باشد.
۲. هالتر را باز بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. هالتر را با کنترل و دست‌های صاف به پشت سر پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس هالتر را به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0037.gif', 'upper-back', 'triceps,chest', '1. Lie on a decline bench with your head lower than your hips and your feet secured.
2. Hold a barbell with a wide grip and extend your arms straight above your chest.
3. Lower the barbell behind your head in a controlled manner, keeping your arms straight.
4. Pause for a moment, then raise the barbell back to the starting position.
5. Repeat for the desired number of repetitions.', '0037') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0038', 'جلو بازو درگ هالتر', 'Barbell drag curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از زیر با کف دست رو به بالا بگیرید.
۲. اجازه دهید هالتر با دست‌های صاف جلوی ران‌ها آویزان باشد.
۳. بازوها را ثابت نگه دارید و با انقباض جلو بازو هالتر را به سمت سینه بالا بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0038.gif', 'biceps', 'forearm', '1. Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.
2. Let the barbell hang at arm''s length in front of your thighs.
3. Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.
4. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0038') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1370', 'ساق پا هالتر روی زمین', 'Barbell floor calf raise', 'legs', 'پا', 'barbell', 'هالتر', 'ساق پا', 'همسترینگ (پشت ران)', '۱. هالتر را روی زمین جلوی خود بگذارید.
۲. پنجه پاها را روی لبه هالتر بگذارید و پاشنه‌ها آزاد باشند.
۳. در صورت نیاز برای حفظ تعادل یک جسم ثابت را بگیرید.
۴. با کمک عضلات ساق، پاشنه‌ها را تا جای ممکن بالا ببرید و بدن را بلند کنید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1370.gif', 'calves', 'hamstring', '1. Place a barbell on the floor in front of you.
2. Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.
3. Hold onto a stable object for balance if needed.
4. Raise your heels as high as possible, using your calves to lift your body.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '1370') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0039', 'اسکوات سینه‌ای هالتر', 'Barbell front chest squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را جلوی سینه با دست‌هایی به اندازه عرض شانه و آرنج‌های رو به جلو نگه دارید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و با بردن لگن به عقب و خم کردن زانوها به حالت اسکوات پایین بروید.
۴. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۵. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0039.gif', 'gluteal', 'quadriceps,hamstring,calves,abs', '1. Start by standing with your feet shoulder-width apart, toes slightly turned out.
2. Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.
3. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.
4. Lower until your thighs are parallel to the ground, or as low as you can comfortably go.
5. Pause for a moment at the bottom, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '0039') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0040', 'نشر جلو و پول‌اور هالتر', 'Barbell front raise and pullover', 'chest', 'سینه', 'barbell', 'هالتر', 'سینه', 'سرشانه، پشت بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو با کف دست رو به پایین بگیرید.
۲. دست‌ها را صاف نگه دارید و هالتر را جلوی بدن تا ارتفاع شانه بالا بیاورید.
۳. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۴. سپس هالتر را با دست‌های صاف به پشت سر ببرید.
۵. لحظه‌ای در پایین مکث کنید، سپس هالتر را به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0040.gif', 'chest', 'deltoids,triceps', '1. Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.
2. Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.
3. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
4. Next, lower the barbell behind your head, keeping your arms straight.
5. Pause for a moment at the bottom, then raise the barbell back up to the starting position.
6. Repeat for the desired number of repetitions.', '0040') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1461', 'اسکوات کامل هالتر (نمای پشت)', 'Barbell full squat (back pov)', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را روی بالای کمر، روی عضلات کول یا دلتوئید خلفی قرار دهید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و شروع به پایین رفتن کنید.
۴. زانوها و لگن را خم کنید و لگن را مانند نشستن روی صندلی به عقب و پایین ببرید.
۵. بدن را تا جایی پایین ببرید که ران‌ها موازی زمین یا کمی پایین‌تر باشند.
۶. زانوها را در راستای پنجه پا و وزن را روی پاشنه‌ها نگه دارید.
۷. با فشار پاشنه‌ها و باز کردن لگن و زانوها دوباره بایستید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1461.gif', 'gluteal', 'quadriceps,hamstring,calves,abs', '1. Stand with your feet shoulder-width apart, toes slightly turned out.
2. Hold the barbell across your upper back, resting it on your traps or rear delts.
3. Engage your core and keep your chest up as you begin to lower your body down.
4. Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.
5. Lower your body until your thighs are parallel to the ground or slightly below.
6. Keep your knees in line with your toes and your weight in your heels.
7. Drive through your heels to stand back up, extending your hips and knees.
8. Repeat for the desired number of repetitions.', '1461') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1462', 'اسکوات کامل هالتر (نمای جانبی)', 'Barbell full squat (side pov)', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را روی بالای کمر، روی عضلات کول یا دلتوئید خلفی قرار دهید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و شروع به پایین رفتن کنید.
۴. زانوها و لگن را خم کنید و لگن را مانند نشستن روی صندلی به عقب و پایین ببرید.
۵. بدن را تا جایی پایین ببرید که ران‌ها موازی زمین یا کمی پایین‌تر باشند.
۶. زانوها را در راستای پنجه پا و وزن را روی پاشنه‌ها نگه دارید.
۷. با فشار پاشنه‌ها و باز کردن لگن و زانوها دوباره بایستید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1462.gif', 'gluteal', 'quadriceps,hamstring,calves,abs', '1. Stand with your feet shoulder-width apart, toes slightly turned out.
2. Hold the barbell across your upper back, resting it on your traps or rear delts.
3. Engage your core and keep your chest up as you begin to lower your body down.
4. Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.
5. Lower your body until your thighs are parallel to the ground or slightly below.
6. Keep your knees in line with your toes and your weight in your heels.
7. Drive through your heels to stand back up, extending your hips and knees.
8. Repeat for the desired number of repetitions.', '1462') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1545', 'اسکوات زرچر کامل هالتر', 'Barbell full zercher squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را در گودی آرنج‌ها نگه دارید و برای ثبات میله را با دست‌ها بگیرید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و لگن را به عقب و پایین ببرید تا به حالت اسکوات برسید.
۴. زانوها را در راستای پنجه پا و وزن را روی پاشنه‌ها نگه دارید.
۵. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۶. با فشار پاشنه‌ها بایستید و در اوج حرکت باسن را منقبض کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1545.gif', 'gluteal', 'quadriceps,hamstring,calves,abs', '1. Stand with your feet shoulder-width apart and toes slightly turned out.
2. Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.
3. Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.
4. Keep your knees in line with your toes and your weight in your heels.
5. Lower until your thighs are parallel to the ground, or as low as you can comfortably go.
6. Drive through your heels to stand back up, squeezing your glutes at the top of the movement.
7. Repeat for the desired number of repetitions.', '1545') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1409', 'پل باسن هالتر', 'Barbell glute bridge', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. به پشت صاف روی زمین دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. هالتر را روی لگن قرار دهید و با هر دو دست محکم نگه دارید.
۳. باسن و میان‌تنه را درگیر کنید و لگن را از زمین بلند کنید تا بدن از زانو تا شانه یک خط صاف بسازد.
۴. لحظه‌ای در بالا مکث کنید و باسن را منقبض کنید.
۵. لگن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1409.gif', 'gluteal', 'hamstring,lower-back', '1. Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.
2. Place a barbell across your hips, holding it securely with both hands.
3. Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.
4. Pause for a moment at the top, squeezing your glutes.
5. Slowly lower your hips back down to the starting position.
6. Repeat for the desired number of repetitions.', '1409') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3562', 'پل باسن هالتر با دو پا روی نیمکت', 'Barbell glute bridge two legs on bench (male)', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، میان‌تنه', '۱. لبه نیمکت بنشینید، بالای کمر را به نیمکت تکیه دهید و کف پاها به اندازه عرض لگن روی زمین باشد.
۲. هالتر را روی لگن قرار دهید و با هر دو دست محکم نگه دارید.
۳. باسن و میان‌تنه را درگیر کنید و با فشار پاشنه‌ها لگن را بالا ببرید تا بدن از زانو تا شانه یک خط صاف بسازد.
۴. لحظه‌ای در بالا مکث کنید و باسن را منقبض کنید.
۵. لگن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3562.gif', 'gluteal', 'hamstring,abs', '1. Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.
2. Place a barbell across your hips, holding it securely with both hands.
3. Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.
4. Pause for a moment at the top, squeezing your glutes.
5. Slowly lower your hips back down to the starting position.
6. Repeat for the desired number of repetitions.', '3562') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0044', 'گودمورنینگ هالتر', 'Barbell good morning', 'legs', 'پا', 'barbell', 'هالتر', 'همسترینگ (پشت ران)', 'پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر روی بالای کمر قرار داشته باشد.
۲. با کمر صاف و میان‌تنه درگیر، از لگن به جلو خم شوید و باسن را به عقب ببرید، گویی می‌خواهید با باسن دیوار پشت سر را لمس کنید.
۳. تنه را پایین ببرید تا موازی زمین شود و کشش را در همسترینگ حس کنید.
۴. لحظه‌ای مکث کنید، سپس با انقباض باسن و راندن لگن به جلو به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0044.gif', 'hamstring', 'lower-back', '1. Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.
2. Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.
3. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.
4. Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.
5. Repeat for the desired number of repetitions.', '0044') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0045', 'پرس سینه گیوتین هالتر', 'Barbell guillotine bench press', 'chest', 'سینه', 'barbell', 'هالتر', 'سینه', 'شانه‌ها، پشت بازو', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را آرام به سمت گردن پایین بیاورید و آرنج‌ها را به سمت بیرون نگه دارید.
۴. وقتی هالتر کمی بالاتر از گردن قرار گرفت لحظه‌ای مکث کنید.
۵. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0045.gif', 'chest', 'deltoids,triceps', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
3. Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.
4. Pause for a moment when the barbell is just above your neck.
5. Push the barbell back up to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '0045') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0046', 'هاک اسکوات هالتر', 'Barbell hack squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را پشت پاها نگه دارید و روی بالای ران‌ها قرار دهید.
۳. با خم کردن زانوها و لگن بدن را پایین ببرید و کمر را صاف و سینه را بالا نگه دارید.
۴. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۵. لحظه‌ای مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0046.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Start by standing with your feet shoulder-width apart and your toes slightly turned out.
2. Hold the barbell behind your legs, resting it on your upper thighs.
3. Lower your body by bending at the knees and hips, keeping your back straight and your chest up.
4. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
5. Pause for a moment, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '0046') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1436', 'اسکوات هالتر بار بالا', 'Barbell high bar squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را روی بالای کمر و روی عضلات کول قرار دهید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و با بردن لگن به عقب و خم کردن زانوها اسکوات بروید.
۴. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۵. با فشار پاشنه‌ها و باز کردن لگن و زانوها دوباره بایستید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1436.gif', 'gluteal', 'quadriceps,hamstring,calves,abs', '1. Stand with your feet shoulder-width apart, toes slightly turned out.
2. Place the barbell on your upper back, resting it on your traps.
3. Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.
4. Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.
5. Drive through your heels to stand back up, extending your hips and knees.
6. Repeat for the desired number of repetitions.', '1436') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1719', 'پرس بالاسینه هالتر دست جمع', 'Barbell incline close grip bench press', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'سینه، شانه‌ها', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی نیمکت دراز بکشید و کف پاها را روی زمین بگذارید.
۳. هالتر را با دست‌های جمع، کمی جمع‌تر از عرض شانه بگیرید.
۴. هالتر را از جایگاه بردارید و آرام به سمت سینه پایین بیاورید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. وقتی هالتر به سینه رسید لحظه‌ای مکث کنید.
۶. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1719.gif', 'triceps', 'chest,deltoids', '1. Set up an incline bench at a 45-degree angle.
2. Lie down on the bench with your feet flat on the ground.
3. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.
5. Pause for a moment when the barbell touches your chest.
6. Push the barbell back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '1719') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0048', 'پرس بالاسینه هالتر دست‌برعکس', 'Barbell incline reverse-grip press', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'سینه، شانه‌ها', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی نیمکت دراز بکشید و هالتر را دست‌برعکس و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را از جایگاه بردارید و به سمت بالای سینه پایین بیاورید و آرنج‌ها را جمع نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس هالتر را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0048.gif', 'triceps', 'chest,deltoids', '1. Set up an incline bench at a 45-degree angle.
2. Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.
3. Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.
4. Pause for a moment at the bottom, then push the barbell back up to the starting position.
5. Repeat for the desired number of repetitions.', '0048') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0049', 'زیربغل هالتر روی نیمکت شیب‌دار', 'Barbell incline row', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'بالای پشت', 'جلو بازو، ساعد', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی نیمکت دمر دراز بکشید، سینه روی پد و کف پاها روی زمین باشد.
۳. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۴. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۵. هالتر را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0049.gif', 'upper-back', 'biceps,forearm', '1. Set up an incline bench at a 45-degree angle.
2. Lie face down on the bench with your chest against the pad and your feet flat on the ground.
3. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
4. Keep your back straight and your core engaged.
5. Pull the barbell towards your chest, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower the barbell back to the starting position.
7. Repeat for the desired number of repetitions.', '0049') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0050', 'بالا آوردن شانه هالتر روی نیمکت شیب‌دار', 'Barbell incline shoulder raise', 'chest', 'سینه', 'barbell', 'هالتر', 'دندانه‌ای قدامی', 'سرشانه، کول (ذوزنقه)', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی نیمکت بنشینید، کمر به پشتی تکیه داشته باشد و کف پاها روی زمین باشد.
۳. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۴. هالتر را تا ارتفاع شانه بالا بیاورید و آرنج‌ها را کمی خم نگه دارید.
۵. هالتر را آرام بالای سر ببرید و دست‌ها را کاملاً صاف کنید.
۶. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام تا ارتفاع شانه پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0050.gif', 'serratus', 'deltoids,trapezius', '1. Set up an incline bench at a 45-degree angle.
2. Sit on the bench with your back against the pad and feet flat on the ground.
3. Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.
4. Lift the barbell up to shoulder height, keeping your elbows slightly bent.
5. Slowly raise the barbell overhead, extending your arms fully.
6. Pause for a moment at the top, then slowly lower the barbell back to shoulder height.
7. Repeat for the desired number of repetitions.', '0050') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0051', 'اسکوات جفرسون هالتر', 'Barbell jefferson squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را از رو بگیرید و جلوی بدن، کمی پایین‌تر از کمر نگه دارید.
۳. پای چپ را جلو و پای راست را عقب بگذارید و فاصله پاها را به اندازه عرض شانه نگه دارید.
۴. زانوها را خم کنید و به حالت اسکوات پایین بروید و کمر را صاف و سینه را بالا نگه دارید.
۵. با فشار پاشنه‌ها بایستید و به وضعیت شروع برگردید.
۶. حرکت را تکرار کنید و در هر تکرار جای پای جلو و عقب را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0051.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart and toes slightly turned out.
2. Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.
3. Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.
4. Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.
5. Push through your heels to stand back up to the starting position.
6. Repeat the movement, alternating your forward and back foot with each repetition.', '0051') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0052', 'پرس سینه جی‌ام هالتر', 'Barbell jm bench press', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را تا سینه پایین بیاورید و آرنج‌ها را جمع و نزدیک بدن نگه دارید.
۴. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0052.gif', 'triceps', 'chest,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
3. Lower the barbell to your chest, keeping your elbows tucked in close to your body.
4. Push the barbell back up to the starting position, fully extending your arms.
5. Repeat for the desired number of repetitions.', '0052') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0053', 'اسکوات پرشی هالتر', 'Barbell jump squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر نگه دارید.
۲. با خم کردن زانوها و بردن لگن به عقب به حالت اسکوات پایین بروید.
۳. در پایین اسکوات، به صورت انفجاری از زمین بپرید.
۴. هنگام پرش، لگن، زانوها و مچ پاها را کاملاً باز کنید و از پنجه پا نیرو بگیرید.
۵. نرم به حالت اسکوات فرود بیایید و بلافاصله حرکت را به تعداد تکرار دلخواه تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0053.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.
2. Lower your body into a squat position by bending your knees and pushing your hips back.
3. Once you reach the bottom of the squat, explode upwards by jumping off the ground.
4. As you jump, extend your hips, knees, and ankles, pushing through your toes.
5. Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions.', '0053') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1410', 'لانج جانبی هالتر', 'Barbell lateral lunge', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر نگه دارید.
۲. با پای راست یک گام بلند به طرف بردارید و پای چپ را ثابت نگه دارید.
۳. زانوی راست را خم کنید و به حالت لانج پایین بروید و پای چپ را صاف نگه دارید.
۴. با فشار پای راست به وضعیت شروع برگردید.
۵. برای طرف دیگر با گام پای چپ تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1410.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a barbell across your upper back.
2. Take a big step to the side with your right foot, keeping your left foot planted.
3. Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.
4. Push off with your right foot and return to the starting position.
5. Repeat on the other side, stepping with your left foot.', '1410') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1435', 'اسکوات هالتر بار پایین', 'Barbell low bar squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر روی بالای کمر قرار داشته باشد.
۲. سینه را بالا و میان‌تنه را درگیر نگه دارید و با خم کردن زانوها و بردن لگن به عقب آرام پایین بروید.
۳. تا جایی پایین بروید که ران‌ها موازی زمین یا کمی پایین‌تر باشند.
۴. لحظه‌ای مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1435.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart and the barbell resting on your upper back.
2. Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.
3. Continue lowering until your thighs are parallel to the ground or slightly below.
4. Pause for a moment, then push through your heels to return to the starting position.
5. Repeat for the desired number of repetitions.', '1435') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0054', 'لانج هالتر', 'Barbell lunge', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر قرار دهید.
۲. با پای راست یک گام به جلو بردارید و تنه را صاف نگه دارید.
۳. با خم کردن زانوی راست بدن را پایین ببرید تا ران موازی زمین شود.
۴. با فشار پاشنه راست به وضعیت شروع برگردید.
۵. با پای چپ تکرار کنید و به تعداد تکرار دلخواه پاها را یکی در میان عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0054.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.
2. Take a step forward with your right foot, keeping your torso upright.
3. Lower your body by bending your right knee until your thigh is parallel to the ground.
4. Push through your right heel to return to the starting position.
5. Repeat with your left leg, alternating legs for the desired number of repetitions.', '0054') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1720', 'پشت بازو خوابیده هالتر از پشت سر', 'Barbell lying back of the head tricep extension', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و سر در انتهای نیمکت باشد.
۲. هالتر را از رو و به اندازه عرض شانه بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. بازوها را ثابت نگه دارید و با خم کردن آرنج‌ها هالتر را آرام به پشت سر پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1720.gif', 'triceps', 'deltoids', '1. Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
2. Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.
3. Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.
4. Pause for a moment, then extend your arms back up to the starting position.
5. Repeat for the desired number of repetitions.', '1720') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0055', 'پرس دست جمع خوابیده هالتر', 'Barbell lying close-grip press', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. هالتر را با دست‌های جمع، به اندازه عرض شانه و کف دست رو به پاها بگیرید.
۳. هالتر را از جایگاه بردارید و با دست‌های کاملاً صاف درست بالای سینه نگه دارید.
۴. هالتر را آرام به سمت سینه پایین بیاورید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. وقتی هالتر به سینه رسید لحظه‌ای مکث کنید، سپس آن را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0055.gif', 'triceps', 'chest,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.
3. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.
4. Slowly lower the barbell towards your chest, keeping your elbows close to your body.
5. Pause for a moment when the barbell touches your chest, then push it back up to the starting position.
6. Repeat for the desired number of repetitions.', '0055') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0056', 'پشت بازو خوابیده دست جمع هالتر', 'Barbell lying close-grip triceps extension', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و سر در انتهای نیمکت باشد.
۲. هالتر را با دست‌های جمع، به اندازه عرض شانه و کف دست رو به بالا بگیرید.
۳. دست‌ها را کاملاً صاف کنید و هالتر را بالای سینه نگه دارید.
۴. بازوها را ثابت نگه دارید و با خم کردن آرنج‌ها هالتر را آرام به سمت پیشانی پایین بیاورید.
۵. لحظه‌ای در پایین مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0056.gif', 'triceps', 'deltoids', '1. Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
2. Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.
3. Extend your arms fully, lifting the barbell above your chest.
4. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.
5. Pause for a moment at the bottom, then extend your arms back to the starting position.
6. Repeat for the desired number of repetitions.', '0056') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0057', 'باز کردن آرنج خوابیده هالتر', 'Barbell lying extension', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و سر در انتهای نیمکت باشد.
۲. هالتر را از رو و به اندازه عرض شانه بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. بازوها را ثابت نگه دارید و با خم کردن آرنج‌ها هالتر را آرام به سمت پیشانی پایین بیاورید.
۴. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0057.gif', 'triceps', 'deltoids', '1. Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
2. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.
3. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.
4. Pause for a moment, then extend your arms back up to the starting position.
5. Repeat for the desired number of repetitions.', '0057') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0058', 'بالا آوردن هالتر خوابیده (روی لگن)', 'Barbell lying lifting (on hip)', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. به پشت روی نیمکت دراز بکشید، کف پاها روی زمین و زانوها خم باشد.
۲. هالتر را از رو بگیرید و روی لگن قرار دهید.
۳. با درگیر کردن باسن، لگن را از نیمکت بلند کنید تا بدن از زانو تا شانه یک خط صاف بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس لگن را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0058.gif', 'gluteal', 'hamstring,quadriceps', '1. Lie flat on your back on a bench with your feet flat on the ground and your knees bent.
2. Hold the barbell with an overhand grip and position it on your hips.
3. Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.
4. Pause for a moment at the top, then slowly lower your hips back down to the starting position.
5. Repeat for the desired number of repetitions.', '0058') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0059', 'جلو بازو لاری خوابیده هالتر', 'Barbell lying preacher curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. روی نیمکت لاری بنشینید، سینه روی پد و دست‌ها از لبه آن صاف باشد و هالتر را از زیر بگیرید.
۲. بازوها را ثابت نگه دارید و با بازدم، وزنه را با انقباض جلو بازو بالا بیاورید.
۳. میله را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و میله در سطح شانه باشد.
۴. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۵. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0059.gif', 'biceps', 'forearm', '1. Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.
2. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
3. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.
4. Hold the contracted position for a brief pause as you squeeze your biceps.
5. Inhale and slowly begin to lower the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '0059') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0061', 'پشت بازو خوابیده هالتر', 'Barbell lying triceps extension', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و سر در انتهای نیمکت باشد.
۲. هالتر را از رو و به اندازه عرض شانه بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. بازوها را ثابت نگه دارید و با خم کردن آرنج‌ها هالتر را آرام به سمت پیشانی پایین بیاورید.
۴. لحظه‌ای در پایین مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0061.gif', 'triceps', 'deltoids', '1. Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
2. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.
3. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.
4. Pause for a moment at the bottom, then extend your arms back up to the starting position.
5. Repeat for the desired number of repetitions.', '0061') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0063', 'اسکوات هالتر با پاهای جمع', 'Barbell narrow stance squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را روی بالای کمر، روی عضلات کول یا دلتوئید خلفی قرار دهید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و با خم کردن زانوها و بردن لگن به عقب آرام پایین بروید.
۴. تا جایی پایین بروید که ران‌ها موازی زمین یا کمی پایین‌تر باشند.
۵. لحظه‌ای مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0063.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart and toes pointing slightly outward.
2. Hold the barbell across your upper back, resting it on your traps or rear delts.
3. Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.
4. Continue lowering until your thighs are parallel to the ground or slightly below.
5. Pause for a moment, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '0063') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0064', 'زیربغل خم تک‌دست هالتر', 'Barbell one arm bent over row', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید، زانوها کمی خم باشد و هالتر را با یک دست و از رو بگیرید.
۲. از لگن به جلو خم شوید، کمر را صاف و سر را در حالت طبیعی نگه دارید.
۳. هالتر را به سمت سینه بالا بکشید، آرنج را نزدیک بدن نگه دارید و کتف‌ها را به هم فشار دهید.
۴. هالتر را با کنترل به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0064.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.
2. Bend forward at the hips, keeping your back straight and your head in a neutral position.
3. Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.
4. Lower the barbell back down to the starting position in a controlled manner.
5. Repeat for the desired number of repetitions, then switch to the other arm.', '0064') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0065', 'پرس زمین تک‌دست هالتر', 'Barbell one arm floor press', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'سینه، شانه‌ها', '۱. به پشت صاف روی زمین دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. هالتر را با یک دست و کف دست رو به بالا بگیرید و دست را صاف بالای سینه نگه دارید.
۳. هالتر را آرام به سمت سینه پایین بیاورید و آرنج را نزدیک بدن نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس هالتر را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0065.gif', 'triceps', 'chest,deltoids', '1. Lie flat on your back on the floor with your knees bent and feet flat on the ground.
2. Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.
3. Slowly lower the barbell towards your chest, keeping your elbow close to your body.
4. Pause for a moment at the bottom, then push the barbell back up to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '0065') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0066', 'ددلیفت جانبی تک‌دست هالتر', 'Barbell one arm side deadlift', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را با یک دست و از رو بگیرید.
۲. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. از لگن خم شوید و هالتر را به سمت بیرون پا پایین ببرید و دست را صاف و سینه را بالا نگه دارید.
۴. هالتر را تا جایی که فرم درست حفظ می‌شود پایین ببرید.
۵. لحظه‌ای مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0066.gif', 'gluteal', 'hamstring,quadriceps,lower-back', '1. Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.
2. Keep your back straight and your core engaged.
3. Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.
4. Lower the barbell as far as you can while maintaining good form.
5. Pause for a moment, then slowly return to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '0066') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0067', 'اسنچ تک‌دست هالتر', 'Barbell one arm snatch', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'کول (ذوزنقه)، ساعد، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. زانوها را خم کنید و لگن را به حالت اسکوات پایین ببرید و کمر را صاف و سینه را بالا نگه دارید.
۴. لگن، زانوها و مچ پاها را انفجاری باز کنید و هالتر را به بالا برانید.
۵. وقتی هالتر به سطح سینه رسید، آن را با دست به بالا بکشید و نزدیک بدن نگه دارید.
۶. آرنج را زیر هالتر بچرخانید و دست را کاملاً بالای سر صاف و آرنج را قفل کنید.
۷. هالتر را با کنترل به وضعیت شروع پایین بیاورید.
۸. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0067.gif', 'deltoids', 'trapezius,forearm,abs', '1. Stand with your feet shoulder-width apart, toes pointing slightly outwards.
2. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.
4. Explosively extend your hips, knees, and ankles, driving the barbell upwards.
5. As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.
6. Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.
7. Lower the barbell back down to the starting position in a controlled manner.
8. Repeat for the desired number of repetitions, then switch arms.', '0067') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0068', 'اسکوات تک‌پا هالتر', 'Barbell one leg squat', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر نگه دارید.
۲. یک پا را از زمین بلند کنید و به جلو و موازی زمین دراز کنید.
۳. پای تکیه‌گاه را خم کنید و مانند نشستن روی صندلی پایین بروید و سینه را بالا و کمر را صاف نگه دارید.
۴. تا جایی پایین بروید که ران موازی زمین شود، سپس با فشار پاشنه به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کرده و تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0068.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet shoulder-width apart and hold a barbell across your upper back.
2. Lift one foot off the ground and extend it forward, keeping it parallel to the ground.
3. Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.
4. Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.
5. Repeat for the desired number of repetitions, then switch legs and repeat.', '0068') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0069', 'اسکوات بالای سر هالتر', 'Barbell overhead squat', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را با دست‌های باز بگیرید و با دست‌های کاملاً صاف بالای سر نگه دارید.
۳. میان‌تنه را درگیر کنید و به حالت اسکوات پایین بروید و سینه را بالا و زانوها را در راستای پنجه پا نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0069.gif', 'quadriceps', 'gluteal,hamstring,calves,abs', '1. Stand with your feet shoulder-width apart and toes slightly turned out.
2. Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.
3. Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.
4. Pause for a moment at the bottom, then push through your heels to return to the starting position.
5. Repeat for the desired number of repetitions.', '0069') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1411', 'مچ دست هالتر کف دست رو به پایین روی نیمکت', 'Barbell palms down wrist curl over a bench', 'arms', 'بازو', 'barbell', 'هالتر', 'ساعد', 'جلو بازو، بازویی', '۱. روی نیمکت بنشینید، کف پاها روی زمین باشد و ساعدها با کف دست رو به پایین روی ران‌ها قرار گیرد.
۲. هالتر را از رو و به اندازه عرض شانه بگیرید.
۳. با خم کردن مچ‌ها هالتر را به سمت زمین پایین ببرید و ساعدها را ثابت نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس با باز کردن مچ‌ها هالتر را آرام بالا بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1411.gif', 'forearm', 'biceps', '1. Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.
2. Hold a barbell with an overhand grip, hands shoulder-width apart.
3. Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.
4. Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.
5. Repeat for the desired number of repetitions.', '1411') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1412', 'مچ دست هالتر کف دست رو به بالا روی نیمکت', 'Barbell palms up wrist curl over a bench', 'arms', 'بازو', 'barbell', 'هالتر', 'ساعد', 'جلو بازو، شانه‌ها', '۱. روی نیمکت بنشینید، کف پاها روی زمین باشد و هالتر را از زیر با کف دست رو به بالا بگیرید.
۲. ساعدها را روی نیمکت بگذارید و اجازه دهید مچ‌ها از لبه آویزان باشند.
۳. ساعدها را ثابت نگه دارید و با بازدم، مچ‌ها را تا جای ممکن به سمت بالا خم کنید.
۴. وضعیت انقباض را لحظه‌ای نگه دارید، سپس با دم هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1412.gif', 'forearm', 'biceps,deltoids', '1. Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.
2. Rest your forearms on the bench, allowing your wrists to hang off the edge.
3. Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.
4. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.
5. Repeat for the desired number of repetitions.', '1412') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3017', 'زیربغل پندلی هالتر', 'Barbell pendlay row', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. از لگن به جلو خم شوید و کمر را صاف و سینه را بالا نگه دارید.
۳. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۴. هالتر را به سمت بالای شکم بکشید و کتف‌ها را به هم فشار دهید.
۵. هالتر را به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3017.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Bend forward at the hips, keeping your back straight and your chest up.
3. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
4. Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.
5. Lower the barbell back down to the starting position.
6. Repeat for the desired number of repetitions.', '3017') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1751', 'پرس پین هالتر', 'Barbell pin presses', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'شانه‌ها', '۱. هالتر را روی رک در ارتفاع سینه قرار دهید.
۲. رو به هالتر بایستید و زیر آن قرار بگیرید و پاها را به اندازه عرض شانه باز کنید.
۳. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۴. هالتر را از رک بردارید و با دست‌های کاملاً صاف درست بالای سینه نگه دارید.
۵. هالتر را به سمت سینه پایین بیاورید و آرنج‌ها را جمع و نزدیک بدن نگه دارید.
۶. وقتی هالتر به سینه رسید لحظه‌ای مکث کنید.
۷. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1751.gif', 'triceps', 'deltoids', '1. Set up a barbell on a power rack at chest height.
2. Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.
3. Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.
4. Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.
5. Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.
6. Pause for a moment when the barbell touches your chest.
7. Push the barbell back up to the starting position, fully extending your arms.
8. Repeat for the desired number of repetitions.', '1751') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0071', 'دراز و نشست با پرس هالتر', 'Barbell press sit-up', 'core', 'شکم و میان‌تنه', 'barbell', 'هالتر', 'شکم', 'شانه‌ها، سینه', '۱. به پشت صاف روی تشک دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. هالتر را از رو بگیرید و روی سینه قرار دهید.
۳. با درگیر کردن عضلات شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0071.gif', 'abs', 'deltoids,chest', '1. Lie flat on your back on a mat with your knees bent and feet flat on the ground.
2. Hold the barbell with an overhand grip, resting it on your chest.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0071') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0072', 'جلو بازو دمر روی نیمکت شیب‌دار هالتر', 'Barbell prone incline curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی نیمکت دمر دراز بکشید، سینه و شکم روی آن باشد.
۳. هالتر را از زیر و به اندازه عرض شانه بگیرید.
۴. دست‌ها را کاملاً صاف کنید تا هالتر به سمت زمین آویزان باشد.
۵. بازوها را ثابت نگه دارید و با بازدم، وزنه را با انقباض جلو بازو بالا بیاورید.
۶. هالتر را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و میله در سطح شانه باشد.
۷. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۸. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید.
۹. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0072.gif', 'biceps', 'forearm', '1. Set up an incline bench at a 45-degree angle.
2. Lie face down on the bench with your chest and stomach resting against it.
3. Hold a barbell with an underhand grip, shoulder-width apart.
4. Extend your arms fully, allowing the barbell to hang down towards the floor.
5. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
6. Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.
7. Hold the contracted position for a brief pause as you squeeze your biceps.
8. Inhale and slowly begin to lower the barbell back to the starting position.
9. Repeat for the desired number of repetitions.', '0072') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0073', 'پول‌اور هالتر', 'Barbell pullover', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'زیربغل', 'سینه، پشت بازو', '۱. روی نیمکت صاف دراز بکشید؛ سر در یک انتهای نیمکت و پاها روی زمین.
۲. هالتر را به اندازه عرض شانه بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. با دست‌های صاف، هالتر را با کنترل به پشت سر ببرید تا کشش را در زیربغل حس کنید.
۴. لحظه‌ای مکث کنید، سپس هالتر را به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0073.gif', 'upper-back', 'chest,triceps', '1. Lie flat on a bench with your head at one end and your feet on the floor.
2. Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.
3. Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.
4. Pause for a moment, then raise the barbell back to the starting position.
5. Repeat for the desired number of repetitions.', '0073') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0022', 'پول‌اور تا پرس هالتر', 'Barbell pullover to press', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'زیربغل', 'پشت بازو، سینه، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید؛ سر در یک انتهای نیمکت و پاها روی زمین.
۲. هالتر را از رو (کف دست رو به جلو) بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. با دست‌های صاف، هالتر را در مسیری کمانی به پشت سر ببرید تا کشش را در زیربغل حس کنید.
۴. لحظه‌ای مکث کنید، سپس حرکت را معکوس کنید و هالتر را به وضعیت شروع بالای سینه برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0022.gif', 'upper-back', 'triceps,chest,deltoids', '1. Lie flat on a bench with your head at one end and your feet on the ground.
2. Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.
3. Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.
4. Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.
5. Repeat for the desired number of repetitions.', '0022') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0074', 'رک پول هالتر', 'Barbell rack pull', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. هالتر را روی رک در ارتفاع زانو قرار دهید.
۲. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۳. با خم کردن لگن و زانوها پایین بروید و هالتر را از رو و به اندازه عرض شانه بگیرید.
۴. میان‌تنه را درگیر کنید و با باز کردن لگن و زانوها هالتر را بلند کنید و در بالا شانه‌ها را عقب کشیده و باسن را منقبض کنید.
۵. با خم کردن لگن و زانوها هالتر را به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0074.gif', 'gluteal', 'hamstring,lower-back', '1. Set up a barbell on a rack at knee height.
2. Stand with your feet shoulder-width apart, toes pointing slightly outwards.
3. Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.
4. Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.
5. Lower the barbell back down to the starting position by bending at the hips and knees.
6. Repeat for the desired number of repetitions.', '0074') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0075', 'نشر دلتوئید خلفی هالتر', 'Barbell rear delt raise', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو با کف دست رو به پایین بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. هالتر را با دست‌های صاف به طرفین بالا بیاورید تا دست‌ها موازی زمین شوند.
۴. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0075.gif', 'deltoids', 'trapezius,upper-back', '1. Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.
4. Pause for a moment at the top, then slowly lower the barbell back to the starting position.
5. Repeat for the desired number of repetitions.', '0075') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0076', 'زیربغل دلتوئید خلفی هالتر', 'Barbell rear delt row', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع، جلو بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. از لگن به جلو خم شوید و کمر را صاف و سینه را بالا نگه دارید.
۴. هالتر را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0076.gif', 'deltoids', 'trapezius,upper-back,biceps', '1. Stand with your feet shoulder-width apart and knees slightly bent.
2. Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Bend forward at the hips, keeping your back straight and chest up.
4. Pull the barbell towards your chest, squeezing your shoulder blades together.
5. Pause for a moment at the top, then slowly lower the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '0076') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0078', 'لانج معکوس هالتر', 'Barbell rear lunge', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر قرار دهید.
۲. با پای راست یک گام به عقب بردارید و روی پنجه پا فرود بیایید.
۳. هر دو زانو را خم کنید و بدن را پایین ببرید تا ران چپ موازی زمین شود.
۴. با فشار پاشنه چپ به وضعیت شروع برگردید.
۵. با پای دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0078.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.
2. Take a step backward with your right foot, landing on the ball of your foot.
3. Bend both knees to lower your body until your left thigh is parallel to the ground.
4. Push through your left heel to return to the starting position.
5. Repeat with the other leg.', '0078') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0077', 'لانج معکوس هالتر (نسخه ۲)', 'Barbell rear lunge v. 2', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر نگه دارید.
۲. با پای راست یک گام به عقب بردارید و روی پنجه پا فرود بیایید.
۳. هر دو زانو را خم کنید و بدن را پایین ببرید تا ران چپ موازی زمین شود.
۴. با فشار پاشنه چپ به وضعیت شروع برگردید.
۵. با پای دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0077.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart and hold a barbell across your upper back.
2. Take a step backward with your right foot, landing on the ball of your foot.
3. Bend both knees to lower your body until your left thigh is parallel to the ground.
4. Push through your left heel to return to the starting position.
5. Repeat with the other leg.', '0077') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0079', 'مچ دست معکوس هالتر (نسخه ۲)', 'Barbell revers wrist curl v. 2', 'arms', 'بازو', 'barbell', 'هالتر', 'ساعد', 'جلو بازو، بازویی', '۱. روی نیمکت بنشینید، کف پاها روی زمین و زانوها خم باشد.
۲. هالتر را از رو با کف دست رو به پایین و دست‌ها به اندازه عرض شانه بگیرید.
۳. ساعدها را روی ران‌ها بگذارید و اجازه دهید مچ‌ها از لبه آویزان باشند.
۴. ساعدها را ثابت نگه دارید و با بازدم، مچ‌ها را تا جای ممکن به سمت بالا خم کنید.
۵. وضعیت انقباض را لحظه‌ای نگه دارید، سپس با دم هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0079.gif', 'forearm', 'biceps', '1. Sit on a bench with your feet flat on the ground and your knees bent.
2. Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.
3. Rest your forearms on your thighs, allowing your wrists to hang off the edge.
4. Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.
5. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '0079') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2187', 'پرس سینه دست‌برعکس دست جمع هالتر', 'Barbell reverse close-grip bench press', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. هالتر را دست‌برعکس و به اندازه عرض شانه بگیرید.
۳. هالتر را از جایگاه بردارید و با دست‌های کاملاً صاف درست بالای سینه نگه دارید.
۴. هالتر را آرام به سمت سینه پایین بیاورید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. وقتی هالتر کمی بالاتر از سینه قرار گرفت لحظه‌ای مکث کنید.
۶. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2187.gif', 'triceps', 'chest,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Grasp the barbell with a reverse grip, hands shoulder-width apart.
3. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.
4. Slowly lower the barbell down towards your chest, keeping your elbows close to your body.
5. Pause for a moment when the barbell is just above your chest.
6. Push the barbell back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '2187') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0080', 'جلو بازو برعکس هالتر', 'Barbell reverse curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو با کف دست رو به پایین بگیرید.
۲. بازوها را ثابت نگه دارید و با بازدم هالتر را با انقباض جلو بازو بالا بیاورید.
۳. هالتر را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و هالتر در سطح شانه باشد.
۴. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۵. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید و بازوها را ثابت نگه دارید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0080.gif', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.
2. Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.
3. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.
4. Hold the contracted position for a brief pause as you squeeze your biceps.
5. Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.
6. Repeat for the desired number of repetitions.', '0080') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0118', 'زیربغل خم دست‌برعکس هالتر', 'Barbell reverse grip bent over row', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. هالتر را از رو با کف دست رو به پایین و کمی بازتر از عرض شانه بگیرید.
۳. از لگن به جلو خم شوید، کمر را صاف و سینه را بالا نگه دارید تا تنه تقریباً موازی زمین شود.
۴. هالتر را به سمت پایین سینه بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0118.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart and knees slightly bent.
2. Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.
3. Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.
4. Pull the barbell towards your lower chest, squeezing your shoulder blades together.
5. Pause for a moment at the top, then slowly lower the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '0118') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1256', 'پرس زیرسینه دست‌برعکس هالتر', 'Barbell reverse grip decline bench press', 'chest', 'سینه', 'barbell', 'هالتر', 'سینه', 'پشت بازو، شانه‌ها', '۱. روی نیمکت زیرسینه دراز بکشید، پاها محکم و سر پایین‌تر از لگن باشد.
۲. هالتر را دست‌برعکس و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را از جایگاه بردارید و آرام به سمت سینه پایین بیاورید و آرنج‌ها را جمع نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس هالتر را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1256.gif', 'chest', 'triceps,deltoids', '1. Lie on a decline bench with your feet secured and your head lower than your hips.
2. Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.
3. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.
4. Pause for a moment at the bottom, then push the barbell back up to the starting position.
5. Repeat for the desired number of repetitions.', '1256') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1257', 'پرس بالاسینه دست‌برعکس هالتر', 'Barbell reverse grip incline bench press', 'chest', 'سینه', 'barbell', 'هالتر', 'سینه', 'پشت بازو، شانه‌ها', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی نیمکت دراز بکشید و کف پاها را روی زمین بگذارید.
۳. هالتر را دست‌برعکس و کمی بازتر از عرض شانه بگیرید.
۴. هالتر را از جایگاه بردارید و آرام به سمت سینه پایین بیاورید و آرنج‌ها را جمع نگه دارید.
۵. وقتی هالتر به سینه رسید لحظه‌ای مکث کنید.
۶. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1257.gif', 'chest', 'triceps,deltoids', '1. Set up an incline bench at a 45-degree angle.
2. Lie down on the bench with your feet flat on the ground.
3. Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.
5. Pause for a moment when the barbell touches your chest.
6. Push the barbell back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '1257') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1317', 'زیربغل روی نیمکت شیب‌دار دست‌برعکس هالتر', 'Barbell reverse grip incline bench row', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'بالای پشت', 'جلو بازو، ساعد', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. رو به پشتی نیمکت بنشینید و سینه را به آن تکیه دهید.
۳. هالتر را دست‌برعکس و کمی بازتر از عرض شانه بگیرید.
۴. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۵. هالتر را به سمت بالای شکم بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در اوج حرکت مکث کنید.
۷. هالتر را آرام به وضعیت شروع پایین بیاورید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1317.gif', 'upper-back', 'biceps,forearm', '1. Set up an incline bench at a 45-degree angle.
2. Sit on the bench facing the backrest with your chest against it.
3. Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.
4. Keep your back straight and core engaged.
5. Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.
6. Pause for a moment at the top of the movement.
7. Slowly lower the barbell back to the starting position.
8. Repeat for the desired number of repetitions.', '1317') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1721', 'پشت بازو جمجمه دست‌برعکس هالتر', 'Barbell reverse grip skullcrusher', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'ساعد', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و سر در انتهای نیمکت باشد.
۲. هالتر را دست‌برعکس با کف دست رو به صورت و به اندازه عرض شانه بگیرید.
۳. دست‌ها را صاف بالای سینه ببرید، آرنج‌ها را جمع و مچ‌ها را صاف نگه دارید.
۴. بازوها را ثابت نگه دارید و با خم کردن آرنج‌ها هالتر را آرام به سمت پیشانی پایین بیاورید.
۵. لحظه‌ای در پایین مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1721.gif', 'triceps', 'forearm', '1. Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
2. Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.
3. Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.
4. Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.
5. Pause for a moment at the bottom, then extend your arms back up to the starting position.
6. Repeat for the desired number of repetitions.', '1721') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0081', 'جلو بازو لاری برعکس هالتر', 'Barbell reverse preacher curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. روی نیمکت لاری بنشینید، سینه روی پد و دست‌ها صاف رو به پایین باشد و هالتر را از رو بگیرید.
۲. بازوها را ثابت نگه دارید و با بازدم هالتر را با انقباض جلو بازو بالا بیاورید.
۳. هالتر را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و هالتر در سطح شانه باشد.
۴. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۵. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0081.gif', 'biceps', 'forearm', '1. Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.
2. Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.
3. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.
4. Hold the contracted position for a brief pause as you squeeze your biceps.
5. Inhale and slowly lower the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '0081') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0082', 'مچ دست معکوس هالتر', 'Barbell reverse wrist curl', 'arms', 'بازو', 'barbell', 'هالتر', 'ساعد', 'جلو بازو، بازویی', '۱. روی نیمکت بنشینید، کف پاها روی زمین باشد و هالتر را از رو با کف دست رو به پایین بگیرید.
۲. ساعدها را روی ران‌ها بگذارید و اجازه دهید مچ‌ها از لبه آویزان باشند.
۳. مچ‌ها را آرام به سمت بالا خم کنید و هالتر را به سمت بدن بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0082.gif', 'forearm', 'biceps', '1. Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.
2. Rest your forearms on your thighs, allowing your wrists to hang off the edge.
3. Slowly curl your wrists upward, bringing the barbell towards your body.
4. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0082') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0084', 'رول‌اوت هالتر', 'Barbell rollerout', 'core', 'شکم و میان‌تنه', 'barbell', 'هالتر', 'شکم', 'پایین کمر', '۱. روی زمین زانو بزنید و هالتر را با دو دست به اندازه عرض شانه بگیرید.
۲. هالتر را به جلو بغلتانید، دست‌ها را باز کنید و میان‌تنه را درگیر نگه دارید.
۳. آن‌قدر به جلو بغلتانید که بدن کاملاً کشیده و دست‌ها بالای سر قرار گیرند.
۴. لحظه‌ای مکث کنید، سپس هالتر را با کنترل به سمت زانوها برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0084.gif', 'abs', 'lower-back', '1. Kneel on the floor and hold a barbell with both hands, shoulder-width apart.
2. Roll the barbell forward, extending your arms and keeping your core engaged.
3. Continue rolling forward until your body is fully extended and your arms are overhead.
4. Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.
5. Repeat for the desired number of repetitions.', '0084') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0083', 'رول‌اوت هالتر از روی نیمکت', 'Barbell rollerout from bench', 'core', 'شکم و میان‌تنه', 'barbell', 'هالتر', 'شکم', 'شانه‌ها، پشت بازو', '۱. روی زمین زانو بزنید و هالتر روی نیمکتی جلوی شما قرار داشته باشد.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. با میان‌تنه درگیر و کمر صاف، هالتر را آرام به جلو بغلتانید و دست‌ها را جلوی بدن باز کنید.
۴. آن‌قدر هالتر را به جلو بغلتانید که بدن کاملاً کشیده و دست‌ها بالای سر قرار گیرند.
۵. لحظه‌ای در حالت کاملاً کشیده مکث کنید، سپس هالتر را آرام به سمت بدن برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0083.gif', 'abs', 'deltoids,triceps', '1. Start by kneeling on the floor with a barbell placed on a bench in front of you.
2. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
3. Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.
4. Continue rolling the barbell forward until your body is fully extended and your arms are overhead.
5. Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.
6. Repeat for the desired number of repetitions.', '0083') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0086', 'سرشانه نظامی پشت گردن نشسته هالتر', 'Barbell seated behind head military press', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. روی نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را از جایگاه بردارید و پشت سر تا سطح شانه پایین بیاورید.
۴. هالتر را به بالا پرس کنید تا دست‌ها کاملاً صاف شوند.
۵. هالتر را به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0086.gif', 'deltoids', 'triceps,upper-back', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.
3. Lift the barbell off the rack and bring it down to shoulder level, behind your head.
4. Press the barbell upward until your arms are fully extended.
5. Lower the barbell back down to the starting position.
6. Repeat for the desired number of repetitions.', '0086') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0087', 'پرس برادفورد راکی نشسته هالتر', 'Barbell seated bradford rocky press', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. روی نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را تا ارتفاع شانه بالا بیاورید، آرنج‌ها کمی خم و رو به جلو باشند.
۴. هالتر را بالای سر پرس کنید و دست‌ها را کاملاً صاف کنید.
۵. هالتر را تا ارتفاع شانه پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0087.gif', 'deltoids', 'triceps,upper-back', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.
3. Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.
4. Press the barbell overhead, fully extending your arms.
5. Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', '0087') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1371', 'ساق پا نشسته هالتر', 'Barbell seated calf raise', 'legs', 'پا', 'barbell', 'هالتر', 'ساق پا', 'همسترینگ (پشت ران)', '۱. روی نیمکت بنشینید، کف پاها روی زمین باشد و هالتر روی ران‌ها قرار گیرد.
۲. پنجه پاها را روی یک سطح بلند مانند بلوک یا پله بگذارید.
۳. پاشنه‌ها را تا جای ممکن پایین ببرید تا کشش را در ساق پا حس کنید.
۴. پاشنه‌ها را تا جای ممکن بالا ببرید و ساق پا را منقبض کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1371.gif', 'calves', 'hamstring', '1. Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.
2. Place the balls of your feet on a raised platform, such as a block or step.
3. Lower your heels as far as possible, feeling a stretch in your calves.
4. Raise your heels as high as possible, contracting your calves.
5. Repeat for the desired number of repetitions.', '1371') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1718', 'پشت بازو پشت گردن دست جمع نشسته هالتر', 'Barbell seated close grip behind neck triceps extension', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. هالتر را با دست‌های جمع پشت گردن و کف دست رو به جلو نگه دارید.
۳. آرنج‌ها را نزدیک سر نگه دارید و هالتر را آرام به سمت پشت سر پایین بیاورید.
۴. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1718.gif', 'triceps', 'deltoids', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold the barbell with a close grip behind your neck, palms facing forward.
3. Keep your elbows close to your head and slowly lower the barbell towards the back of your head.
4. Pause for a moment, then extend your arms back up to the starting position.
5. Repeat for the desired number of repetitions.', '1718') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0089', 'جلو بازو تمرکزی دست جمع نشسته هالتر', 'Barbell seated close-grip concentration curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. روی نیمکت بنشینید، کف پاها روی زمین باشد و هالتر را از زیر و به اندازه عرض شانه بگیرید.
۲. بازوها را به داخل ران‌ها، کمی بالاتر از زانوها تکیه دهید و هالتر را جلوی بدن آویزان کنید.
۳. بازوها را ثابت نگه دارید و با بازدم هالتر را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۴. وضعیت انقباض را لحظه‌ای نگه دارید، سپس با دم هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0089.gif', 'biceps', 'forearm', '1. Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.
2. Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.
3. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.
4. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0089') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0090', 'گودمورنینگ نشسته هالتر', 'Barbell seated good morning', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. روی نیمکت بنشینید، کف پاها روی زمین باشد و هالتر روی بالای کمر قرار گیرد.
۲. کمر را صاف و سینه را بالا نگه دارید.
۳. آرام از لگن به جلو خم شوید و تنه را به سمت زمین پایین ببرید.
۴. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0090.gif', 'gluteal', 'hamstring,lower-back', '1. Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.
2. Keep your back straight and your chest up.
3. Slowly hinge forward at the hips, lowering your torso towards the ground.
4. Pause for a moment at the bottom, then push through your heels to return to the starting position.
5. Repeat for the desired number of repetitions.', '0090') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0091', 'پرس سرشانه نشسته هالتر', 'Barbell seated overhead press', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. روی نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را از جایگاه بردارید و با آرنج‌های خم و کف دست رو به جلو تا سطح شانه بیاورید.
۴. با صاف کردن کامل دست‌ها هالتر را بالای سر پرس کنید.
۵. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام تا سطح شانه پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0091.gif', 'deltoids', 'triceps,upper-back', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.
3. Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.
4. Press the barbell overhead by extending your arms fully.
5. Pause for a moment at the top, then slowly lower the barbell back to shoulder level.
6. Repeat for the desired number of repetitions.', '0091') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0092', 'پشت بازو بالای سر نشسته هالتر', 'Barbell seated overhead triceps extension', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. هالتر را از رو و به اندازه عرض شانه بگیرید و بالای سر ببرید.
۳. با خم کردن آرنج‌ها هالتر را پشت سر پایین ببرید و بازوها را نزدیک سر نگه دارید.
۴. لحظه‌ای مکث کنید، سپس با صاف کردن دست‌ها هالتر را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0092.gif', 'triceps', 'deltoids', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.
3. Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.
4. Pause for a moment, then extend your arms to raise the barbell back to the starting position.
5. Repeat for the desired number of repetitions.', '0092') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0094', 'چرخش تنه نشسته با هالتر', 'Barbell seated twist', 'core', 'شکم و میان‌تنه', 'barbell', 'هالتر', 'شکم', 'پهلوها، پایین کمر', '۱. روی نیمکت صاف بنشینید، کف پاها روی زمین و زانوها خم باشد.
۲. هالتر را با دو دست جلوی سینه نگه دارید و آرنج‌ها را کمی خم کنید.
۳. میان‌تنه را درگیر کنید و تنه را آرام به یک طرف بچرخانید و کمر را صاف نگه دارید.
۴. لحظه‌ای در انتهای چرخش مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. چرخش را به طرف دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0094.gif', 'abs', 'obliques,lower-back', '1. Sit on a flat bench with your feet flat on the ground and your knees bent.
2. Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.
3. Engage your core and slowly twist your torso to one side, keeping your back straight.
4. Pause for a moment at the end of the twist, then slowly rotate back to the starting position.
5. Repeat the twist to the other side.
6. Continue alternating sides for the desired number of repetitions.', '0094') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0096', 'خم شدن جانبی هالتر (نسخه ۲)', 'Barbell side bent v. 2', 'core', 'شکم و میان‌تنه', 'barbell', 'هالتر', 'شکم', 'پهلوها، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را با دو دست و کف دست رو به پایین بگیرید.
۲. در طول تمرین کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. تنه را آرام به سمت راست خم کنید و هالتر را به سمت زانوی راست پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس به وضعیت شروع برگردید.
۵. حرکت را برای سمت چپ تکرار کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0096.gif', 'abs', 'obliques,lower-back', '1. Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.
2. Keep your back straight and core engaged throughout the exercise.
3. Slowly bend your torso to the right side, lowering the barbell towards your right knee.
4. Pause for a moment, then return to the starting position.
5. Repeat the movement on the left side.
6. Continue alternating sides for the desired number of repetitions.', '0096') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0098', 'اسکوات اسپلیت جانبی هالتر', 'Barbell side split squat', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را بازتر از عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را روی بالای کمر و روی عضلات کول قرار دهید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و با خم کردن زانوها و لگن به حالت اسکوات پایین بروید.
۴. هنگام پایین رفتن، زانوها را به طرفین باز کنید و وزن را روی پاشنه‌ها نگه دارید.
۵. تا جایی پایین بروید که ران‌ها موازی زمین شوند، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0098.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.
2. Hold a barbell across your upper back, resting it on your traps.
3. Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.
4. As you lower, push your knees out to the sides and keep your weight on your heels.
5. Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '0098') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0097', 'اسکوات اسپلیت جانبی هالتر (نسخه ۲)', 'Barbell side split squat v. 2', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را بازتر از عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را روی بالای کمر و روی شانه‌ها قرار دهید.
۳. با پای راست یک گام بلند به طرف بردارید و پای چپ را ثابت نگه دارید.
۴. زانوی راست را خم کنید و به حالت اسکوات پایین بروید و سینه را بالا و کمر را صاف نگه دارید.
۵. با فشار پاشنه راست به وضعیت شروع برگردید.
۶. برای طرف دیگر با گام پای چپ تکرار کنید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0097.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.
2. Hold a barbell across your upper back, resting it on your shoulders.
3. Take a big step to the side with your right foot, keeping your left foot planted.
4. Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.
5. Push through your right heel to return to the starting position.
6. Repeat on the other side, stepping out with your left foot.
7. Continue alternating sides for the desired number of repetitions.', '0097') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1756', 'ددلیفت تک‌پا هالتر', 'Barbell single leg deadlift', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. بایستید، پاها را به اندازه عرض لگن باز کنید و هالتر را جلوی ران‌ها از رو بگیرید.
۲. وزن را روی پای چپ منتقل کنید و پای راست را کمی از زمین بلند کنید.
۳. از لگن به جلو خم شوید، کمر را صاف نگه دارید و برای تعادل پای راست را پشت سر دراز کنید.
۴. هالتر را نزدیک بدن به سمت زمین پایین ببرید و پای چپ را کمی خم نگه دارید.
۵. لحظه‌ای در پایین مکث کنید، سپس با درگیر کردن باسن و همسترینگ تنه را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1756.gif', 'gluteal', 'hamstring,lower-back', '1. Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.
2. Shift your weight onto your left foot and lift your right foot slightly off the ground.
3. Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.
4. Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.
5. Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '1756') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0099', 'اسکوات اسپلیت تک‌پا هالتر', 'Barbell single leg split squat', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر نگه دارید.
۲. با یک پا یک گام بلند به جلو بردارید و تنه را صاف نگه دارید.
۳. با خم کردن زانو و لگن پای جلو بدن را پایین ببرید و پای عقب را صاف نگه دارید.
۴. تا جایی پایین بروید که ران پای جلو موازی زمین شود.
۵. لحظه‌ای مکث کنید، سپس با فشار پاشنه پای جلو به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0099.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a barbell across your upper back.
2. Take a large step forward with one leg, keeping your torso upright.
3. Lower your body by bending your front knee and hip, while keeping your back leg straight.
4. Continue lowering until your front thigh is parallel to the ground.
5. Pause for a moment, then push through your front heel to return to the starting position.
6. Repeat for the desired number of repetitions, then switch legs.', '0099') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2799', 'بالا آوردن پا یک در میان نشسته با هالتر', 'Barbell sitted alternate leg raise', 'core', 'شکم و میان‌تنه', 'barbell', 'هالتر', 'شکم', 'خم‌کننده ران', '۱. روی نیمکت با کمر صاف بنشینید و هالتر را روی ران‌ها نگه دارید.
۲. با پاهای صاف، یک پا را تا جای ممکن بالا ببرید و پای دیگر روی زمین بماند.
۳. پای بالا را پایین بیاورید و با پای دیگر تکرار کنید.
۴. به تعداد تکرار دلخواه، پاها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2799.gif', 'abs', 'hip-flexors', '1. Sit on a bench with your back straight and hold a barbell across your thighs.
2. Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.
3. Lower the raised leg back down and repeat with the other leg.
4. Continue alternating legs for the desired number of repetitions.', '2799') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2800', 'بالا آوردن پا یک در میان نشسته با هالتر (بانوان)', 'Barbell sitted alternate leg raise (female)', 'core', 'شکم و میان‌تنه', 'barbell', 'هالتر', 'شکم', 'خم‌کننده ران، چهارسر ران', '۱. روی نیمکت با کمر صاف بنشینید و هالتر را روی ران‌ها نگه دارید.
۲. برای حمایت، دست‌ها را روی لبه‌های نیمکت بگذارید.
۳. با پاهای صاف، یک پا را تا جای ممکن بالا ببرید و موازی زمین نگه دارید.
۴. پا را پایین بیاورید و با پای دیگر تکرار کنید.
۵. به تعداد تکرار دلخواه، پاها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2800.gif', 'abs', 'hip-flexors,quadriceps', '1. Sit on a bench with your back straight and hold a barbell across your thighs.
2. Place your hands on the sides of the bench for support.
3. Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.
4. Lower the leg back down and repeat with the other leg.
5. Continue alternating legs for the desired number of repetitions.', '2800') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0100', 'اسکی‌باز هالتر', 'Barbell skier', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را جلوی ران‌ها از رو بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف و سینه را بالا نگه دارید.
۳. همزمان هالتر را به سمت شانه‌ها بالا بیاورید و کمی از زمین بپرید.
۴. در اوج حرکت، سریع حرکت را معکوس کنید و هالتر را به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0100.gif', 'deltoids', 'triceps,abs', '1. Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.
3. Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.
4. As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0100') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0101', 'اسکوات سرعتی هالتر', 'Barbell speed squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را روی بالای کمر، روی عضلات کول یا دلتوئید خلفی قرار دهید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و لگن را مانند نشستن روی صندلی به عقب و پایین ببرید.
۴. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۵. با فشار پاشنه‌ها بایستید و در بالا باسن را منقبض کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0101.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, toes slightly turned out.
2. Hold the barbell across your upper back, resting it on your traps or rear delts.
3. Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.
4. Lower until your thighs are parallel to the ground, or as low as you can comfortably go.
5. Drive through your heels to stand back up, squeezing your glutes at the top.
6. Repeat for the desired number of repetitions.', '0101') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2810', 'اسکوات اسپلیت هالتر (نسخه ۲)', 'Barbell split squat v. 2', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر نگه دارید.
۲. با پای راست یک گام بلند به جلو بردارید و تنه را صاف نگه دارید.
۳. با خم کردن زانوها و لگن بدن را پایین ببرید تا ران راست موازی زمین شود.
۴. لحظه‌ای مکث کنید، سپس با فشار پاشنه راست به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه با پای چپ جلو تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2810.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.
2. Take a large step forward with your right foot, keeping your torso upright.
3. Lower your body by bending your knees and hips until your right thigh is parallel to the ground.
4. Pause for a moment, then push through your right heel to return to the starting position.
5. Repeat with your left leg forward for the desired number of repetitions.', '2810') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0102', 'اسکوات روی زانو هالتر', 'Barbell squat (on knees)', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. روی زمین زانو بزنید، زانوها به اندازه عرض لگن باز و پنجه پاها رو به جلو باشد.
۲. هالتر را روی شانه‌ها قرار دهید و از رو و کمی بازتر از عرض شانه بگیرید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و با خم کردن زانوها و کمر صاف آرام پایین بروید.
۴. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۵. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0102.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.
2. Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.
3. Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.
4. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
5. Pause for a moment at the bottom, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '0102') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2798', 'اسکوات پرشی و لانج معکوس هالتر', 'Barbell squat jump step rear lunge', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر نگه دارید.
۲. با خم کردن زانوها و بردن لگن به عقب به حالت اسکوات پایین بروید.
۳. به صورت انفجاری تا جای ممکن از زمین بپرید.
۴. نرم روی پاها فرود بیایید و بلافاصله با یک پا به عقب گام بردارید و لانج معکوس انجام دهید.
۵. بدن را پایین ببرید تا ران پای جلو موازی زمین شود و کمر را صاف نگه دارید.
۶. با فشار پاشنه پای جلو به وضعیت شروع برگردید.
۷. توالی پرش و لانج را با پای دیگر تکرار کنید.
۸. به تعداد تکرار دلخواه، پاها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2798.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.
2. Lower your body into a squat position by bending your knees and pushing your hips back.
3. Explode upwards, jumping off the ground as high as you can.
4. Land softly on your feet and immediately step back with one leg into a reverse lunge.
5. Lower your body down until your front thigh is parallel to the ground, keeping your back straight.
6. Push through your front heel to return to the starting position.
7. Repeat the jump and lunge sequence on the other leg.
8. Continue alternating legs for the desired number of repetitions.', '2798') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0103', 'رول‌اوت ایستاده هالتر', 'Barbell standing ab rollerout', 'core', 'شکم و میان‌تنه', 'barbell', 'هالتر', 'شکم', 'شانه‌ها، پایین کمر', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را با دو دست جلوی ران‌ها نگه دارید.
۲. میان‌تنه را درگیر کنید و هالتر را آرام به سمت زمین بغلتانید و کمر را صاف و دست‌ها را کشیده نگه دارید.
۳. آن‌قدر هالتر را به جلو بغلتانید که بدن کاملاً کشیده و دست‌ها درست بالای سر قرار گیرند.
۴. لحظه‌ای مکث کنید، سپس هالتر را با کنترل و میان‌تنه درگیر به سمت ران‌ها برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0103.gif', 'abs', 'deltoids,lower-back', '1. Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.
2. Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.
3. Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.
4. Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.
5. Repeat for the desired number of repetitions.', '0103') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0104', 'مچ دست از پشت ایستاده هالتر', 'Barbell standing back wrist curl', 'arms', 'بازو', 'barbell', 'هالتر', 'ساعد', 'جلو بازو، شانه‌ها', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو بگیرید.
۲. هالتر را روی پشت دست‌ها قرار دهید، کف دست رو به پایین و انگشتان رو به بدن.
۳. بازوها را ثابت نگه دارید و با بازدم مچ‌ها را تا جای ممکن به سمت بالا خم کنید.
۴. وضعیت انقباض را لحظه‌ای نگه دارید، سپس با دم هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0104.gif', 'forearm', 'biceps,deltoids', '1. Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.
2. Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.
3. Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.
4. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.
5. Repeat for the desired number of repetitions.', '0104') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0105', 'پرس برادفورد ایستاده هالتر', 'Barbell standing bradford press', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را جلوی شانه‌ها از رو نگه دارید.
۲. هالتر را بالای سر پرس کنید و دست‌ها را کاملاً صاف کنید.
۳. هالتر را به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0105.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.
2. Press the barbell overhead, fully extending your arms.
3. Lower the barbell back down to the starting position.
4. Repeat for the desired number of repetitions.', '0105') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1372', 'ساق پا ایستاده هالتر', 'Barbell standing calf raise', 'legs', 'پا', 'barbell', 'هالتر', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر قرار دهید.
۲. فقط با کمک پنجه‌ها، پاشنه‌ها را تا جای ممکن از زمین بلند کنید.
۳. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1372.gif', 'calves', 'hamstring,gluteal', '1. Stand with your feet shoulder-width apart and place a barbell across your upper back.
2. Raise your heels off the ground as high as possible, using only your toes.
3. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
4. Repeat for the desired number of repetitions.', '1372') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0106', 'جلو بازو دست جمع ایستاده هالتر', 'Barbell standing close grip curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از زیر با دست‌های جمع بگیرید.
۲. در تمام حرکت آرنج‌ها را نزدیک تنه و بازوها را ثابت نگه دارید.
۳. با بازدم وزنه را با انقباض جلو بازو بالا بیاورید و تا جایی ادامه دهید که جلو بازو کاملاً منقبض شود و میله در سطح شانه باشد.
۴. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۵. با دم، هالتر را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0106.gif', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.
2. Keep your elbows close to your torso and your upper arms stationary throughout the movement.
3. Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.
4. Hold the contracted position for a brief pause as you squeeze your biceps.
5. Inhale as you slowly begin to bring the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '0106') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2414', 'جلو بازو تمرکزی ایستاده هالتر', 'Barbell standing concentration curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را با یک دست و کف دست رو به بالا بگیرید.
۲. برای حمایت دست دیگر را روی ران بگذارید.
۳. بازو را ثابت نگه دارید و با بازدم وزنه را به سمت شانه بالا بیاورید.
۴. لحظه‌ای در بالا مکث کنید و جلو بازو را منقبض کنید.
۵. با دم، وزنه را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2414.gif', 'biceps', 'forearm', '1. Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.
2. Rest your opposite hand on your thigh for support.
3. Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.
4. Pause for a moment at the top, squeezing your biceps.
5. Inhale and slowly lower the weight back down to the starting position.
6. Repeat for the desired number of repetitions, then switch arms.', '2414') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0107', 'نشر جلو تا بالای سر ایستاده هالتر', 'Barbell standing front raise over head', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را جلوی ران‌ها از رو بگیرید.
۲. کمر را صاف نگه دارید و میان‌تنه را درگیر کنید.
۳. هالتر را آرام جلوی بدن بالا بیاورید و دست‌ها را صاف و کف دست را رو به پایین نگه دارید.
۴. تا جایی بالا ببرید که هالتر کمی بالاتر از سطح شانه قرار گیرد.
۵. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0107.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.
2. Keep your back straight and engage your core.
3. Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.
4. Continue lifting until the barbell is slightly above shoulder level.
5. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
6. Repeat for the desired number of repetitions.', '0107') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0108', 'ساق پا ایستاده تک‌پا هالتر', 'Barbell standing leg calf raise', 'legs', 'پا', 'barbell', 'هالتر', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر قرار دهید.
۲. با کمک عضلات ساق، پاشنه‌ها را تا جای ممکن از زمین بلند کنید.
۳. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0108.gif', 'calves', 'hamstring,gluteal', '1. Stand with your feet shoulder-width apart and place a barbell across your upper back.
2. Raise your heels off the ground as high as possible, using your calves.
3. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
4. Repeat for the desired number of repetitions.', '0108') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0109', 'پشت بازو بالای سر ایستاده هالتر', 'Barbell standing overhead triceps extension', 'arms', 'بازو', 'barbell', 'هالتر', 'پشت بازو', 'شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو بگیرید.
۲. هالتر را بالای سر ببرید و دست‌ها را کاملاً صاف کنید.
۳. بازوها را نزدیک سر نگه دارید و با خم کردن آرنج‌ها هالتر را آرام پشت سر پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس با صاف کردن دست‌ها هالتر را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0109.gif', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.
2. Raise the barbell overhead, fully extending your arms.
3. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.
4. Pause for a moment, then raise the barbell back to the starting position by extending your arms.
5. Repeat for the desired number of repetitions.', '0109') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0110', 'جلو بازو دست‌برعکس ایستاده هالتر', 'Barbell standing reverse grip curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از زیر با کف دست رو به بالا بگیرید.
۲. آرنج‌ها را نزدیک تنه و بازوها را ثابت نگه دارید.
۳. با بازدم وزنه را با انقباض جلو بازو بالا بیاورید و هالتر را تا جای ممکن به شانه‌ها نزدیک کنید.
۴. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۵. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0110.gif', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.
2. Keep your elbows close to your torso and your upper arms stationary.
3. Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.
4. Hold the contracted position for a brief pause as you squeeze your biceps.
5. Inhale and slowly lower the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '0110') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0111', 'ساق پا ایستاده نوسانی هالتر', 'Barbell standing rocking leg calf raise', 'legs', 'پا', 'barbell', 'هالتر', 'ساق پا', 'همسترینگ (پشت ران)، چهارسر ران', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را روی بالای کمر نگه دارید.
۲. پاشنه‌ها را تا جای ممکن از زمین بلند کنید و روی پنجه پاها تعادل داشته باشید.
۳. پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0111.gif', 'calves', 'hamstring,quadriceps', '1. Stand with your feet shoulder-width apart and hold a barbell across your upper back.
2. Raise your heels off the ground as high as possible, balancing on the balls of your feet.
3. Slowly lower your heels back down to the starting position.
4. Repeat for the desired number of repetitions.', '0111') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0112', 'چرخش تنه ایستاده با هالتر', 'Barbell standing twist', 'core', 'شکم و میان‌تنه', 'barbell', 'هالتر', 'شکم', 'پهلوها، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را با دو دست و کف دست رو به پایین جلوی سینه نگه دارید.
۲. در طول تمرین میان‌تنه را درگیر و کمر را صاف نگه دارید.
۳. تنه را آرام به راست بچرخانید، روی پاها و لگن بچرخید و پایین‌تنه را ثابت نگه دارید.
۴. لحظه‌ای در انتهای چرخش مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. چرخش را به سمت چپ تکرار کنید.
۶. به تعداد تکرار دلخواه، چرخش‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0112.gif', 'abs', 'obliques,lower-back', '1. Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.
2. Engage your core and keep your back straight throughout the exercise.
3. Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.
4. Pause for a moment at the end of the twist, then slowly return to the starting position.
5. Repeat the twist to the left side.
6. Continue alternating twists for the desired number of repetitions.', '0112') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1629', 'جلو بازو دست باز ایستاده هالتر', 'Barbell standing wide grip biceps curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از زیر و بازتر از عرض شانه بگیرید.
۲. کمر را صاف و آرنج‌ها را نزدیک تنه نگه دارید.
۳. با بازدم هالتر را به سمت شانه‌ها بالا بیاورید و بازوها را ثابت نگه دارید.
۴. لحظه‌ای در بالا مکث کنید و جلو بازو را منقبض کنید.
۵. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1629.gif', 'biceps', 'forearm', '1. Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.
2. Keep your back straight and your elbows close to your torso.
3. Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.
4. Pause for a moment at the top, squeezing your biceps.
5. Inhale and slowly lower the barbell back to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '1629') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1457', 'پرس سرشانه نظامی دست باز ایستاده هالتر', 'Barbell standing wide military press', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۲. هالتر را تا ارتفاع شانه بالا بیاورید و آرنج‌ها را کمی جلوتر از میله نگه دارید.
۳. هالتر را بالای سر پرس کنید و دست‌ها را کاملاً صاف کنید.
۴. هالتر را تا ارتفاع شانه پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1457.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.
2. Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.
3. Press the barbell overhead, extending your arms fully.
4. Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', '1457') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0113', 'جلو بازو دست باز ایستاده هالتر (نسخه ۲)', 'Barbell standing wide-grip curl', 'arms', 'بازو', 'barbell', 'هالتر', 'جلو بازو', 'ساعد، شانه‌ها', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو و بازتر از عرض شانه بگیرید.
۲. هالتر را با دست‌های صاف جلوی ران‌ها آویزان کنید و کف دست‌ها رو به بیرون باشد.
۳. بازوها را ثابت نگه دارید و با بازدم هالتر را با انقباض جلو بازو بالا بیاورید.
۴. هالتر را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و هالتر در سطح شانه باشد.
۵. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۶. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0113.gif', 'biceps', 'forearm,deltoids', '1. Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.
2. Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body.
3. Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.
4. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly begin to lower the barbell back to the starting position.
7. Repeat for the desired number of repetitions.', '0113') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0114', 'استپ‌آپ هالتر', 'Barbell step-up', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. جلوی نیمکت یا پله بایستید و هالتر را روی بالای کمر قرار دهید.
۲. یک پا را روی نیمکت یا پله بگذارید و مطمئن شوید تمام کف پا روی سطح است.
۳. با فشار پاشنه روی نیمکت یا پله بروید و لگن و زانو را کاملاً صاف کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس به وضعیت شروع پایین بیایید.
۵. با پای مقابل تکرار کنید.
۶. به تعداد تکرار دلخواه، پاها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0114.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand in front of a bench or step with a barbell resting on your upper back.
2. Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.
3. Push through your heel and step up onto the bench or step, fully extending your hip and knee.
4. Pause briefly at the top, then lower yourself back down to the starting position.
5. Repeat with the opposite leg.
6. Continue alternating legs for the desired number of repetitions.', '0114') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0115', 'گودمورنینگ پا صاف هالتر', 'Barbell stiff leg good morning', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. هالتر را روی بالای کمر و روی عضلات کول قرار دهید.
۳. با کمر صاف از لگن به جلو خم شوید و باسن را به عقب ببرید.
۴. تنه را پایین ببرید تا موازی زمین شود و کشش را در همسترینگ حس کنید.
۵. با درگیر کردن باسن و همسترینگ به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0115.gif', 'gluteal', 'hamstring,lower-back', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Hold the barbell across your upper back, resting it on your traps.
3. Keeping your back straight, hinge forward at the hips, pushing your glutes back.
4. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.
5. Engage your glutes and hamstrings to return to the starting position.
6. Repeat for the desired number of repetitions.', '0115') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0116', 'ددلیفت پا مستقیم هالتر', 'Barbell straight leg deadlift', 'legs', 'پا', 'barbell', 'هالتر', 'همسترینگ (پشت ران)', 'سرینی (باسن)، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها رو به جلو باشد.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. از لگن خم شوید و هالتر را به سمت زمین پایین ببرید و کمر را صاف و زانوها را کمی خم نگه دارید.
۴. هالتر را تا جایی پایین ببرید که کشش را در همسترینگ حس کنید.
۵. با درگیر کردن همسترینگ و باسن هالتر را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0116.gif', 'hamstring', 'gluteal,lower-back', '1. Stand with your feet shoulder-width apart and your toes pointing forward.
2. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.
4. Lower the barbell until you feel a stretch in your hamstrings.
5. Engage your hamstrings and glutes to lift the barbell back up to the starting position.
6. Repeat for the desired number of repetitions.', '0116') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0117', 'ددلیفت سومو هالتر', 'Barbell sumo deadlift', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، پایین کمر', '۱. بایستید، پاها را بازتر از عرض شانه باز کنید و پنجه‌ها را به بیرون بچرخانید.
۲. هالتر را روی زمین جلوی خود و در وسط دو پا قرار دهید.
۳. زانوها را خم کنید و لگن را پایین ببرید، کمر را صاف و سینه را بالا نگه دارید و هالتر را از رو بگیرید.
۴. میان‌تنه را درگیر کنید و با فشار پاشنه‌ها هالتر را از زمین بلند کنید و همزمان لگن و زانوها را باز کنید.
۵. هنگام بلند کردن سینه را بالا و کمر را صاف نگه دارید و لگن را به جلو برانید تا باسن کاملاً درگیر شود.
۶. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام و با کنترل به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0117.gif', 'gluteal', 'hamstring,quadriceps,lower-back', '1. Stand with your feet wider than shoulder-width apart, toes pointing outwards.
2. Place a barbell on the ground in front of you, centered between your feet.
3. Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.
4. Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.
5. As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.
6. Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.
7. Repeat for the desired number of repetitions.', '0117') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3305', 'تراستر هالتر', 'Barbell thruster', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'چهارسر ران، سرینی (باسن)، همسترینگ (پشت ران)، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو در ارتفاع شانه نگه دارید.
۲. با خم کردن زانوها و بردن لگن به عقب به حالت اسکوات پایین بروید.
۳. در پایین اسکوات، با فشار انفجاری پاشنه‌ها بایستید و همزمان هالتر را بالای سر پرس کنید.
۴. هنگام بازگشت به حالت اسکوات، هالتر را تا ارتفاع شانه پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3305.gif', 'deltoids', 'quadriceps,gluteal,hamstring,abs', '1. Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.
2. Lower into a squat position by bending your knees and pushing your hips back.
3. As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.
4. Lower the barbell back to shoulder height as you lower back into the squat position.
5. Repeat for the desired number of repetitions.', '3305') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0120', 'کول ایستاده هالتر', 'Barbell upright row', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'کول (ذوزنقه)، جلو بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۲. هالتر را با دست‌های کاملاً صاف جلوی ران‌ها آویزان کنید.
۳. با کمر صاف و میان‌تنه درگیر، با بازدم هالتر را با هدایت آرنج‌ها مستقیم به سمت چانه بالا بکشید.
۴. لحظه‌ای در بالا مکث کنید، سپس با دم هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0120.gif', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.
2. Let the barbell hang in front of your thighs, arms fully extended.
3. Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.
4. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0120') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0119', 'کول ایستاده هالتر (نسخه ۲)', 'Barbell upright row v. 2', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'کول (ذوزنقه)، جلو بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۲. هالتر را با دست‌های کاملاً صاف جلوی ران‌ها آویزان کنید.
۳. با کمر صاف و بازدم، هالتر را با هدایت آرنج‌ها مستقیم به سمت چانه بالا بکشید.
۴. لحظه‌ای در بالا مکث کنید، سپس با دم هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0119.gif', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.
2. Let the barbell hang in front of your thighs, arms fully extended.
3. Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.
4. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0119') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0121', 'کول ایستاده هالتر (نسخه ۳)', 'Barbell upright row v. 3', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'کول (ذوزنقه)، جلو بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۲. هالتر را با دست‌های کاملاً صاف جلوی ران‌ها آویزان کنید.
۳. با میان‌تنه درگیر و کمر صاف، هنگام بازدم هالتر را با هدایت آرنج‌ها مستقیم به سمت چانه بالا بکشید.
۴. لحظه‌ای در بالا مکث کنید، سپس هنگام دم هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0121.gif', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.
2. Let the barbell hang in front of your thighs, arms fully extended.
3. Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.
4. Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0121') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0122', 'پرس سینه دست باز هالتر', 'Barbell wide bench press', 'chest', 'سینه', 'barbell', 'هالتر', 'سینه', 'شانه‌ها، پشت بازو', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. هالتر را باز و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را از جایگاه بردارید و با دست‌های کاملاً صاف درست بالای سینه نگه دارید.
۴. هالتر را آرام به سمت سینه پایین بیاورید و آرنج‌ها را کمی به بیرون باز نگه دارید.
۵. وقتی هالتر به سینه رسید لحظه‌ای مکث کنید، سپس آن را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0122.gif', 'chest', 'deltoids,triceps', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.
3. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.
4. Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.
5. Pause for a moment when the barbell touches your chest, then push it back up to the starting position.
6. Repeat for the desired number of repetitions.', '0122') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1258', 'پرس سینه دست‌برعکس دست باز هالتر', 'Barbell wide reverse grip bench press', 'chest', 'سینه', 'barbell', 'هالتر', 'سینه', 'پشت بازو، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. هالتر را دست‌برعکس و باز، کمی بازتر از عرض شانه بگیرید.
۳. هالتر را از جایگاه بردارید و با دست‌های کاملاً صاف درست بالای سینه نگه دارید.
۴. هالتر را آرام به سمت سینه پایین بیاورید، آرنج‌ها را جمع و مچ‌ها را صاف نگه دارید.
۵. وقتی هالتر به سینه رسید لحظه‌ای مکث کنید، سپس آن را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1258.gif', 'chest', 'triceps,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.
3. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.
4. Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.
5. Pause for a moment when the barbell touches your chest, then push it back up to the starting position.
6. Repeat for the desired number of repetitions.', '1258') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0124', 'اسکوات پا باز هالتر', 'Barbell wide squat', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را بازتر از عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را روی بالای کمر، روی عضلات کول یا دلتوئید خلفی قرار دهید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و با بردن لگن به عقب و خم کردن زانوها اسکوات بروید.
۴. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۵. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0124.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.
2. Hold the barbell across your upper back, resting it on your traps or rear delts.
3. Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.
4. Lower until your thighs are parallel to the ground, or as low as you can comfortably go.
5. Pause for a moment at the bottom, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '0124') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0123', 'کول ایستاده دست باز هالتر', 'Barbell wide-grip upright row', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'کول (ذوزنقه)، جلو بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو و بازتر از عرض شانه بگیرید.
۲. هالتر را با دست‌های کاملاً صاف جلوی ران‌ها آویزان کنید.
۳. با کمر صاف و بازدم، هالتر را با هدایت آرنج‌ها مستقیم به سمت چانه بالا بکشید.
۴. لحظه‌ای در بالا مکث کنید، سپس با دم هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0123.gif', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.
2. Let the barbell hang in front of your thighs, arms fully extended.
3. Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.
4. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0123') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0126', 'مچ دست هالتر', 'Barbell wrist curl', 'arms', 'بازو', 'barbell', 'هالتر', 'ساعد', 'جلو بازو، بازویی', '۱. روی نیمکت بنشینید، کف پاها روی زمین و ساعدها روی ران‌ها باشد و هالتر را از زیر بگیرید.
۲. اجازه دهید هالتر تا نوک انگشتان پایین بغلتد و مچ‌ها را صاف نگه دارید.
۳. با خم کردن مچ‌ها هالتر را آرام به سمت ساعدها بالا بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0126.gif', 'forearm', 'biceps', '1. Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.
2. Allow the barbell to roll down to your fingertips, keeping your wrists straight.
3. Slowly curl the barbell up towards your forearms by flexing your wrists.
4. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0126') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0127', 'اسکوات زرچر هالتر', 'Barbell zercher squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. هالتر را در گودی آرنج‌ها نگه دارید و برای ثبات میله را با دست‌ها بگیرید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و لگن را به عقب و پایین ببرید تا به حالت اسکوات برسید.
۴. زانوها را در راستای پنجه پا و وزن را روی پاشنه‌ها نگه دارید.
۵. لحظه‌ای در پایین اسکوات مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0127.gif', 'gluteal', 'quadriceps,hamstring,calves,abs', '1. Stand with your feet shoulder-width apart and toes slightly turned out.
2. Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.
3. Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.
4. Keep your knees in line with your toes and your weight in your heels.
5. Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '0127') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3212', 'لمس پنجه پا ساده', 'Basic toe touch (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها کنار بدن باشد.
۲. از کمر به جلو خم شوید و کمر را صاف و زانوها را کمی خم نگه دارید.
۳. دست‌ها را به سمت پنجه پاها ببرید و پاها را تا جای ممکن صاف نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3212.gif', 'gluteal', 'hamstring,calves', '1. Stand with your feet shoulder-width apart and your arms by your sides.
2. Bend forward at the waist, keeping your back straight and your knees slightly bent.
3. Reach down towards your toes with your hands, keeping your legs as straight as possible.
4. Pause for a moment at the bottom, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '3212') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0128', 'طناب نبرد', 'Battling ropes', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'ساعد، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. هر سر طناب را در یک دست بگیرید، کف دست‌ها رو به هم.
۳. دست‌ها را تا ارتفاع شانه بالا بیاورید و آرنج‌ها را کمی خم نگه دارید.
۴. با بالا و پایین بردن سریع هر دست، موج‌های یکی در میان در طناب‌ها ایجاد کنید.
۵. برای مدت یا تعداد تکرار دلخواه ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0128.gif', 'deltoids', 'forearm,abs', '1. Stand with your feet shoulder-width apart and knees slightly bent.
2. Hold one end of the rope in each hand, with your palms facing each other.
3. Raise your arms to shoulder height, keeping your elbows slightly bent.
4. Begin making alternating waves with the ropes by rapidly raising and lowering each arm.
5. Continue for the desired duration or number of repetitions.', '0128') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1259', 'کشش سینه با دست پشت سر', 'Behind head chest stretch', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'شانه‌ها، پشت بازو', '۱. صاف بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. انگشتان را پشت سر در هم قفل کنید و آرنج‌ها را به بیرون باز کنید.
۳. کتف‌ها را آرام به هم فشار دهید و سینه را به جلو بدهید.
۴. کشش را ۱۵ تا ۳۰ ثانیه نگه دارید.
۵. کشش را رها کنید و به دلخواه تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1259.gif', 'chest', 'deltoids,triceps', '1. Stand tall with your feet shoulder-width apart.
2. Interlace your fingers behind your head with your elbows pointing outwards.
3. Slowly squeeze your shoulder blades together and push your chest forward.
4. Hold the stretch for 15-30 seconds.
5. Release the stretch and repeat as desired.', '1259') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0129', 'دیپ نیمکت (زانو خم)', 'Bench dip (knees bent)', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. لبه نیمکت یا صندلی بنشینید و لبه آن را کنار لگن با دست‌ها بگیرید.
۲. باسن را از نیمکت جلو ببرید و پاها را جلوی بدن صاف کنید و پاشنه‌ها روی زمین بماند.
۳. آرنج‌ها را خم کنید و بدن را به سمت زمین پایین ببرید و کمر را نزدیک نیمکت نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0129.gif', 'triceps', 'chest,deltoids', '1. Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.
2. Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.
3. Bend your elbows and lower your body towards the ground, keeping your back close to the bench.
4. Pause for a moment at the bottom, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '0129') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1399', 'دیپ نیمکت روی زمین', 'Bench dip on floor', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. لبه نیمکت یا صندلی بنشینید و لبه آن را با دست‌ها بگیرید، انگشتان رو به جلو.
۲. باسن را از نیمکت جلو ببرید و وزن بدن را روی دست‌ها نگه دارید.
۳. با خم کردن آرنج‌ها بدن را پایین ببرید تا بازوها موازی زمین شوند.
۴. با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1399.gif', 'triceps', 'chest,deltoids', '1. Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.
2. Slide your butt off the bench, supporting your weight with your hands.
3. Lower your body by bending your elbows until your upper arms are parallel to the floor.
4. Push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '1399') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0130', 'باز کردن لگن روی نیمکت', 'Bench hip extension', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)', '۱. روی نیمکت بنشینید، کمر به نیمکت تکیه داشته باشد و کف پاها روی زمین باشد.
۲. برای حمایت دست‌ها را روی نیمکت بگذارید.
۳. باسن و همسترینگ را درگیر کنید و لگن را از نیمکت بلند کنید تا بدن از زانو تا شانه یک خط صاف بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس لگن را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0130.gif', 'gluteal', 'hamstring', '1. Sit on a bench with your back against the bench and your feet flat on the ground.
2. Place your hands on the bench for support.
3. Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.
4. Pause for a moment at the top, then slowly lower your hips back down to the starting position.
5. Repeat for the desired number of repetitions.', '0130') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3019', 'بارفیکس با نیمکت', 'Bench pull-ups', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. زیر یک میله یا سطح افقی محکم در ارتفاع سینه قرار بگیرید.
۲. میله یا سطح را از رو و کمی بازتر از عرض شانه بگیرید.
۳. با دست‌های کاملاً صاف و بدن صاف آویزان شوید.
۴. با فشردن کتف‌ها به هم و خم کردن آرنج‌ها، سینه را به سمت میله یا سطح بکشید.
۵. تا جایی بالا بروید که چانه بالای میله یا سطح قرار گیرد.
۶. با کنترل به وضعیت شروع پایین بیایید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3019.gif', 'upper-back', 'biceps,forearm', '1. Position yourself under a bar or a sturdy horizontal surface that is at chest height.
2. Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.
3. Hang with your arms fully extended and your body straight.
4. Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.
5. Continue pulling until your chin is above the bar or surface.
6. Lower yourself back down to the starting position with control.
7. Repeat for the desired number of repetitions.', '3019') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3639', 'چرخش تنه خوابیده با زانوی خم', 'Bent knee lying twist (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'پهلوها، خم‌کننده ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را به طرفین و عمود بر بدن باز کنید.
۳. زانوها را جفت نگه دارید و آرام به یک طرف پایین ببرید تا زانوها به زمین برسند.
۴. لحظه‌ای مکث کنید، سپس میان‌تنه را درگیر کنید و زانوها را آرام به وضعیت شروع برگردانید.
۵. حرکت را به طرف دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3639.gif', 'gluteal', 'obliques,hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Extend your arms out to the sides, perpendicular to your body.
3. Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.
4. Pause for a moment, then engage your core and slowly lift your knees back to the starting position.
5. Repeat the movement to the other side.
6. Continue alternating sides for the desired number of repetitions.', '3639') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1770', 'جلو بازو تمرکزی با کمک پا', 'Biceps leg concentration curl', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'جلو بازو', 'ساعد', '۱. روی نیمکت بنشینید، پاها را باز کنید و کف پاها روی زمین باشد.
۲. یک دمبل را در یک دست بگیرید و آرنج را روی داخل ران، کمی بالاتر از زانو قرار دهید.
۳. با کف دست رو به بالا، دمبل را به سمت شانه بالا بیاورید و بازو را ثابت نگه دارید.
۴. در اوج حرکت جلو بازو را منقبض کنید، سپس دمبل را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1770.gif', 'biceps', 'forearm', '1. Sit on a bench with your legs spread apart and your feet flat on the ground.
2. Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.
3. With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.
4. Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '1770') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0139', 'بارفیکس دست جمع جلو بازو', 'Biceps narrow pull-ups', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'جلو بازو', 'ساعد، شانه‌ها', '۱. از میله بارفیکس با کف دست رو به خود و دست‌ها به اندازه عرض شانه آویزان شوید.
۲. میان‌تنه را درگیر کنید و خود را به سمت میله بالا بکشید و روی استفاده از جلو بازو تمرکز کنید.
۳. لحظه‌ای در بالا مکث کنید، سپس آرام به وضعیت شروع پایین بیایید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0139.gif', 'biceps', 'forearm,deltoids', '1. Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.
2. Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.
3. Pause for a moment at the top, then slowly lower yourself back down to the starting position.
4. Repeat for the desired number of repetitions.', '0139') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0140', 'بارفیکس جلو بازو', 'Biceps pull-up', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'جلو بازو', 'ساعد، شانه‌ها', '۱. از میله بارفیکس با کف دست رو به جلو و دست‌ها به اندازه عرض شانه آویزان شوید.
۲. میان‌تنه را درگیر کنید و با خم کردن آرنج‌ها خود را بالا بکشید و سینه را به میله نزدیک کنید.
۳. در اوج حرکت مکث کنید، سپس آرام به وضعیت شروع پایین بیایید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0140.gif', 'biceps', 'forearm,deltoids', '1. Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.
2. Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.
3. Pause at the top of the movement, then slowly lower yourself back down to the starting position.
4. Repeat for the desired number of repetitions.', '0140') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0137', 'بادی‌آپ', 'Body-up', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. دست‌ها را روی یک سطح بلند مانند نیمکت یا پارالل بگذارید، کف دست رو به پایین و انگشتان رو به جلو.
۲. پاها را جلوی بدن دراز کنید، پاشنه‌ها روی زمین و بدن صاف باشد.
۳. با خم کردن آرنج‌ها و نگه داشتن آن‌ها نزدیک بدن، پایین بروید تا بازوها موازی زمین شوند.
۴. لحظه‌ای مکث کنید، سپس با فشار کف دست‌ها، دست‌ها را صاف کنید و به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0137.gif', 'triceps', 'chest,deltoids', '1. Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.
2. Extend your legs out in front of you, keeping your heels on the ground and your body straight.
3. Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.
4. Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.
5. Repeat for the desired number of repetitions.', '0137') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3543', 'اسکوات پرشی با فرود از ارتفاع', 'Bodyweight drop jump squat', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. با خم کردن زانوها و بردن لگن به عقب به حالت اسکوات پایین بروید.
۳. با باز کردن لگن، زانوها و مچ پاها به صورت انفجاری بپرید.
۴. در هوا پاها را سریع به هم نزدیک کنید.
۵. نرم روی پنجه پاها فرود بیایید و بلافاصله به حالت اسکوات برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3543.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart.
2. Lower your body into a squat position by bending your knees and pushing your hips back.
3. Jump up explosively, extending your hips, knees, and ankles.
4. While in mid-air, quickly bring your feet together.
5. Land softly on the balls of your feet and immediately drop back into a squat position.
6. Repeat for the desired number of repetitions.', '3543') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3544', 'پلانک پهلو شیب‌دار با وزن بدن', 'Bodyweight incline side plank', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، شانه‌ها', '۱. به پهلو دراز بکشید و پاها را صاف و روی هم قرار دهید.
۲. ساعد را درست زیر شانه روی زمین بگذارید و آرنج را ۹۰ درجه خم کنید.
۳. میان‌تنه را درگیر کنید و لگن را از زمین بلند کنید تا بدن از سر تا پا یک خط صاف بسازد.
۴. این وضعیت را برای مدت دلخواه نگه دارید.
۵. لگن را به زمین برگردانید و برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3544.gif', 'abs', 'obliques,deltoids', '1. Start by lying on your side with your legs extended and stacked on top of each other.
2. Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.
3. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.
4. Hold this position for the desired amount of time.
5. Lower your hips back down to the ground and repeat on the other side.', '3544') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1771', 'پشت بازو زانو زده با وزن بدن', 'Bodyweight kneeling triceps extension', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'شانه‌ها، سینه', '۱. روی زمین زانو بزنید و زانوها را به اندازه عرض لگن باز کنید.
۲. دست‌ها را جلوی خود به اندازه عرض شانه روی زمین بگذارید، انگشتان رو به جلو.
۳. پاها را صاف پشت سر دراز کنید و روی پنجه پاها و دست‌ها تعادل بگیرید تا بدن از سر تا پاشنه یک خط صاف بسازد.
۴. آرنج‌ها را خم کنید و بالاتنه را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. لحظه‌ای در پایین مکث کنید، سپس با فشار دست‌ها، دست‌ها را صاف کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1771.gif', 'triceps', 'deltoids,chest', '1. Kneel down on the ground with your knees hip-width apart.
2. Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.
3. Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.
4. Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.
5. Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.
6. Repeat for the desired number of repetitions.', '1771') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1769', 'جلو بازو خوابیده به پهلو با وزن بدن', 'Bodyweight side lying biceps curl', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'جلو بازو', 'ساعد', '۱. به پهلو دراز بکشید، پاها صاف باشد و سر را روی دست تکیه دهید.
۲. بازو را به پهلو بچسبانید و با خم کردن آرنج ساعد را به سمت شانه بیاورید.
۳. لحظه‌ای در بالا مکث کنید، سپس ساعد را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1769.gif', 'biceps', 'forearm', '1. Lie on your side with your legs extended and your head supported by your arm.
2. Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.
3. Pause for a moment at the top, then slowly lower your forearm back down to the starting position.
4. Repeat for the desired number of repetitions.', '1769') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3168', 'قایقی در حالت اسکوات با وزن بدن', 'Bodyweight squatting row', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و با دست‌های صاف یک جسم محکم یا تی‌آر‌ایکس را بگیرید.
۲. به حالت اسکوات پایین بروید، کمر را صاف و زانوها را پشت پنجه پاها نگه دارید.
۳. از حالت اسکوات بدن را به سمت جسم یا تی‌آر‌ایکس بالا بکشید و کتف‌ها را به هم فشار دهید.
۴. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3168.gif', 'upper-back', 'biceps,deltoids', '1. Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.
2. Lower your body into a squat position, keeping your back straight and your knees behind your toes.
3. From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.
4. Pause for a moment at the top, then slowly lower your body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3168') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3167', 'قایقی در حالت اسکوات با حوله', 'Bodyweight squatting row (with towel)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و حوله‌ای را جلوی بدن با کف دست رو به پایین بگیرید.
۲. زانوها را خم کنید و به حالت اسکوات پایین بروید، کمر را صاف و سینه را بالا نگه دارید.
۳. همزمان با پایین رفتن در اسکوات، حوله را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.
۴. لحظه‌ای در پایین اسکوات مکث کنید، سپس آرام با صاف کردن دست‌ها به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3167.gif', 'upper-back', 'biceps,deltoids', '1. Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.
2. Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.
3. As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.
4. Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.
5. Repeat for the desired number of repetitions.', '3167') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1373', 'ساق پا ایستاده با وزن بدن', 'Bodyweight standing calf raise', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'مچ پا، پاها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها رو به جلو باشد.
۲. برای تعادل دست‌ها را روی دیوار یا یک سطح ثابت بگذارید.
۳. پاشنه‌ها را آرام از زمین بلند کنید و وزن بدن را روی پنجه پاها ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1373.gif', 'calves', '', '1. Stand with your feet shoulder-width apart, toes pointing forward.
2. Place your hands on a wall or stable surface for balance.
3. Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.
4. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
5. Repeat for the desired number of repetitions.', '1373') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3156', 'قایقی تک‌دست دست جمع ایستاده با وزن بدن', 'Bodyweight standing close-grip one arm row', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز و زانوها کمی خم باشد و یک دمبل را با گرفتن خنثی در یک دست بگیرید.
۲. از لگن به جلو خم شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. دمبل را به سمت سینه بالا بکشید، آرنج را نزدیک بدن نگه دارید و کتف‌ها را به هم فشار دهید.
۴. لحظه‌ای در بالا مکث کنید، سپس دمبل را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3156.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.
2. Bend forward at the hips, keeping your back straight and your core engaged.
3. Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.
4. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '3156') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3158', 'قایقی دست جمع ایستاده با وزن بدن', 'Bodyweight standing close-grip row', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. از کمر به جلو خم شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. دست‌ها را صاف جلوی بدن دراز کنید و میله یا دستگیره‌ها را با دست‌های جمع بگیرید.
۴. میله یا دستگیره‌ها را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در اوج حرکت مکث کنید، سپس آرام رها کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3158.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart and knees slightly bent.
2. Bend forward at the waist, keeping your back straight and your core engaged.
3. Extend your arms straight in front of you, gripping the bar or handles with a close grip.
4. Pull the bar or handles towards your body, squeezing your shoulder blades together.
5. Pause for a moment at the top of the movement, then slowly release and return to the starting position.
6. Repeat for the desired number of repetitions.', '3158') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3162', 'قایقی تک‌دست ایستاده با وزن بدن', 'Bodyweight standing one arm row', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز و زانوها کمی خم باشد و یک دمبل را در یک دست بگیرید.
۲. از لگن به جلو خم شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. دمبل را با دست کاملاً صاف جلوی بدن آویزان کنید.
۴. دمبل را به سمت سینه بالا بکشید و آرنج را نزدیک بدن نگه دارید.
۵. در اوج حرکت کتف‌ها را به هم فشار دهید.
۶. دمبل را به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3162.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.
2. Bend forward at the hips, keeping your back straight and your core engaged.
3. Let the dumbbell hang straight down in front of you, with your arm fully extended.
4. Pull the dumbbell up towards your chest, keeping your elbow close to your body.
5. Squeeze your shoulder blades together at the top of the movement.
6. Lower the dumbbell back down to the starting position.
7. Repeat for the desired number of repetitions, then switch sides.', '3162') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3161', 'قایقی تک‌دست ایستاده با حوله', 'Bodyweight standing one arm row (with towel)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز و زانوها کمی خم باشد و حوله را با یک دست بگیرید.
