INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3166', 'قایقی ایستاده با وزن بدن', 'Bodyweight standing row', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. میله یا دستگیره‌ها را از رو با کف دست رو به پایین بگیرید.
۳. کمر را صاف و میان‌تنه را درگیر نگه دارید.
